// Analyse-workflow: leest de multipart-upload en bouwt per document een
// Docling-item (base64). Elk document krijgt een docType-label
// (bank / kadaster / overig) op basis van de bestandsnaam; alle documenten
// gaan door naar de juridische analyse.

const webhookItem = $input.first();
const b = (webhookItem && webhookItem.binary) || {};
const keys = Object.keys(b);

// Deze workflow kent maar één flow; 'mode' blijft in de items staan omdat
// downstream-nodes (Extract Markdown, specialist-prompts) het veld doorgeven.
const mode = 'analyse';

// Zaaksoort: de context die de gebruiker in de webapp meegeeft, zodat de
// analyse op de juiste transactie wordt gericht (hypotheekvestiging of
// eigendomsoverdracht). Het veld komt als gewoon formulierveld mee in de
// multipart-upload; afhankelijk van de n8n-versie staat het in body of in de
// json-root, dus beide worden gelezen. Onbekende of ontbrekende waarde valt
// terug op 'hypotheek' — dat was het gedrag vóór deze keuze bestond.
// Er kunnen er meerdere tegelijk spelen: een A-B-levering met de hypotheekakte
// er direct achteraan is een gewone passeerdag. De keuze komt als
// komma-gescheiden lijst mee ('levering,hypotheek'). De vaste volgorde
// hieronder is tegelijk de canonieke sleutel: 'hypotheek+levering' — daar hangt
// registry.zaaksoort_context aan, zodat een combinatie een eigen tekst kan
// hebben in plaats van twee losse die elkaar tegenspreken.
const ZAAKSOORTEN = ['hypotheek', 'levering'];
const zaaksoortRuw = String(
  webhookItem?.json?.body?.zaaksoort
  ?? webhookItem?.json?.zaaksoort
  ?? webhookItem?.json?.query?.zaaksoort
  ?? ''
).trim().toLowerCase();
const gekozen = zaaksoortRuw.split(',').map((s) => s.trim()).filter(Boolean);
const zaaksoorten = ZAAKSOORTEN.filter((s) => gekozen.includes(s));
if (!zaaksoorten.length) zaaksoorten.push('hypotheek');
const zaaksoort = zaaksoorten.join('+');

if (keys.length === 0) {
  throw new Error(
    'Webhook ontving geen binary bestanden. Stuur PDF- of Word-bestanden (.docx) als multipart/form-data mee.'
  );
}

function isConvertibleDoc(k) {
  const fn = String(b[k]?.fileName || '').toLowerCase();
  const mime = String(b[k]?.mimeType || '').toLowerCase();
  if (fn.endsWith('.pdf') || mime.includes('pdf')) return true;
  if (fn.endsWith('.docx')) return true;
  if (mime.includes('wordprocessingml') || mime.includes('officedocument.wordprocessingml')) return true;
  return false;
}

const docKeys = keys.filter(isConvertibleDoc);
if (docKeys.length === 0) {
  throw new Error(
    'Geen ondersteunde documenten (PDF of .docx) in de upload.'
  );
}

async function loadAsBase64(binaryKey) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  return buffer.toString('base64');
}

const base = {
  receivedAt: new Date().toISOString(),
  mode,
  zaaksoort,
  zaaksoorten,
};

const BANK_RX_LEGACY = /passeer|nti|rabobank|abnamro|abn[\s_-]?amro|ing|obvion|munt|bank|stater/;
const KAD_RX_LEGACY = /eigendom|kadaster/;

function bankScore(fname) {
  const f = String(fname || '').toLowerCase();
  if (
    /passeerbevestig|passeergegevens|gelden\s+notaris|conceptnota|factuur|\bwwft\b|bankpas|definitieve\s+set|uitbetaling/i.test(f)
  ) {
    return -100;
  }
  let s = 0;
  if (/passeeropdracht/i.test(f)) s += 200;
  if (/notarisinstructie|voorlopige\s+gegevens/i.test(f)) s += 180;
  if (/rabobank|co[oö]peratieve\s+rabo|abn|abnamro|\bing\b|obvion|regiobank|florius|aegon|asr/i.test(f)) s += 85;
  if (/\bnti\b|nutsworth|stater/i.test(f)) s += 85;
  if (/\bpasseer\b/i.test(f) && !/bevestig|melding|gegevens/i.test(f)) s += 35;
  if (/voorlopig/i.test(f)) s -= 40;
  return s;
}

function isKadasterName(fname) {
  const f = String(fname || '').toLowerCase();
  if (/passeeropdracht|notarisinstructie/i.test(f)) return false;
  if (/passeerbevestig|\bwwft\b|\bfactuur\b|bankpas|uitbetaling|\.eml|conceptnota|nota\s+-/i.test(f)) {
    return false;
  }
  return /kadastraal|hypothecair|eigendom|kadaster|objectlijst|rechthebbende|brondocument|uittreksel|kadastrale\s+kaart|hypotheekakte|\bkik\b|\bhyp\d|onroerende\s+zaken|perceel/i.test(f);
}

const items = [];
for (const k of docKeys) {
  const fname = String(b[k]?.fileName || '').toLowerCase();
  let docType = 'overig';
  if (bankScore(fname) >= 50) docType = 'bank';
  else if (isKadasterName(fname) || KAD_RX_LEGACY.test(fname)) docType = 'kadaster';
  const blob = await loadAsBase64.call(this, k);
  items.push({
    json: {
      ...base,
      docType,
      filename: b[k]?.fileName || `${k}.pdf`,
      base64_string: blob,
    },
  });
}
return items;

// Per Docling-response: pak de markdown en bewaar docType + mode + bestandsnaam.
const sourceItem = $('Split Input Files').itemMatching($itemIndex);
const docType = sourceItem?.json?.docType || $json.docType || 'overig';
const mode = sourceItem?.json?.mode || 'akte';
const filename = sourceItem?.json?.filename || '';

const payload = $json;
let md = '';
if (payload?.document?.md_content) md = payload.document.md_content;
else if (payload?.md_content) md = payload.md_content;
else if (payload?.result?.document?.md_content) md = payload.result.document.md_content;
else if (Array.isArray(payload?.documents) && payload.documents[0]?.md_content) md = payload.documents[0].md_content;

if (!md) {
  throw new Error(`Docling gaf geen md_content terug voor ${filename || docType}. Top-level keys: ${Object.keys(payload || {}).join(', ')}`);
}

// Strip ingesloten afbeeldingen. Docling sluit soms volledige bitmaps als
// base64 data-URI in de markdown in (bv. een BRP-uitdraai met logo/foto).
// Die ruis vult de LLM-context (gemeten tot 70%+ van de prompt) en doet het
// model onzin/gibberish produceren. We verwijderen de beelddata; de
// leesbare tekst blijft volledig intact.
function stripEmbeddedImages(text) {
  let t = String(text || '');
  // Markdown-afbeelding met data-URI: ![alt](data:image/png;base64,....)
  t = t.replace(/!\[[^\]]*\]\(\s*data:[^)]*\)/gi, '');
  // HTML <img src="data:...">
  t = t.replace(/<img[^>]*src=["']?data:[^>]*>/gi, '');
  // Vangnet: overgebleven kale data-URI's (contigue base64-reeks).
  t = t.replace(/data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]+/gi, '');
  // Opruimen: 3+ opeenvolgende lege regels terugbrengen naar 1 lege regel.
  t = t.replace(/\n{3,}/g, '\n\n');
  return t.trim();
}

md = stripEmbeddedImages(md);

return { json: { docType, mode, filename, markdown: md } };

const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Create Job').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

werkJobBij({ status: 'analyseren', fase: 2 });

// Analyse-flow (mode='analyse'): voegt alle aangeleverde markdowns samen tot
// één blok dat als één prompt aan de juridische-analyse-LLM gestuurd kan
// worden. Werkt voor 1..N PDFs.
// Zaaksoort komt uit de upload (webapp) en stuurt vanaf hier de bewoording en
// de prompts; 'hypotheek' is de terugval.
const zaaksoorten = (() => {
  try {
    const v = $('Split Input Files').first()?.json?.zaaksoorten;
    return Array.isArray(v) && v.length ? v : ['hypotheek'];
  } catch (_) { return ['hypotheek']; }
})();
const zaaksoort = zaaksoorten.join('+');
const heeftLevering = zaaksoorten.includes('levering');
const heeftHypotheek = zaaksoorten.includes('hypotheek');

const items = $input.all();
if (!items.length) {
  throw new Error('Geen markdowns ontvangen voor de analyse-flow.');
}

const MAX_PER_DOC = 12000;

// Docling zet afbeeldingen als base64 data-URI ín de markdown. Bij een
// kadasteruitdraai is 81% van de tekst zo'n blob, bij een BRP-inzage 93% en bij
// een hypothecair bericht 84%. Dat vult het contextvenster met ruis, duwt de
// echte tekst uit de clamp en laat het model op onzin reageren: de
// partijen-extractie antwoordde er letterlijk op dat de invoer "een
// willekeurige tekencombinatie" was, en leverde dus geen namen. Eruit, vóór de
// clamp — de analyse doet niets met plaatjes.
function zonderAfbeeldingen(md) {
  return String(md || '').replace(/!\[[^\]]*\]\(data:[^)]{100,}\)/g, '[afbeelding]');
}

function clamp(s, max) {
  const txt = String(s || '');
  if (txt.length <= max) return txt;
  return txt.slice(0, max) + '\n…[afgekapt voor analyse-prompt]';
}

function docTypeLabel(t) {
  if (t === 'bank') return 'Bank-passeeropdracht';
  if (t === 'kadaster') return 'Kadaster eigendomsinformatie';
  return 'Document';
}

const docs = items.map((it, i) => {
  const j = it.json || {};
  return {
    index: i + 1,
    docType: j.docType || 'overig',
    filename: j.filename || `document_${i + 1}.pdf`,
    markdown: clamp(zonderAfbeeldingen(j.markdown), MAX_PER_DOC)
  };
});

// --- Welke bronsoorten zitten er écht in de upload? ------------------------
// De docType-labels komen uit de bestandsnaam, en dossiers zitten vol hernoemde
// downloads; die naam zegt dus lang niet altijd wat een stuk is. Het label wordt
// daarom op de inhoud bijgetrokken, en daarna leggen we vast welke bronsoorten
// aanwezig zijn. Zonder die vaststelling schrijven de specialisten over stukken
// die er niet zijn ("de kadastrale eigendomsinformatie toont …" terwijl de
// upload alleen BRP-uitdraaien bevatte).
function isKadasterUitdraai(md) {
  const t = String(md || '');
  if (/Eigendomsinformatie|Hypotheekinformatie|Kadastraal bericht|Hypothecair bericht/i.test(t)) return true;
  if (/Onroerende\s+Zaken\s+Hyp\s*\d/i.test(t)) return true;
  return /BETREFT/.test(t) && /UW\s+REFERENTIE/i.test(t) && /Kadastrale\s+aanduiding/i.test(t);
}
function isBrpInzage(md) {
  const t = String(md || '');
  if (/BRP[-\s]?bevraging/i.test(t)) return true;
  return /\bBSN\b/.test(t) && /Geslachtsnaam/.test(t) && /Geboorteplaats/.test(t);
}
function isOpdrachtStuk(md) {
  const t = String(md || '');
  if (heeftLevering && /\bkoopovereenkomst\b|\bkoopakte\b|\bleveringsopdracht\b|\bopdracht\s+tot\s+levering\b|\bverkoper\b.*\bkoper\b/i.test(t)) return true;
  if (heeftHypotheek && /\bpasseeropdracht\b|\bnotarisinstructie\b/i.test(t)) return true;
  return false;
}
for (const d of docs) {
  if (d.docType !== 'kadaster' && isKadasterUitdraai(d.markdown)) d.docType = 'kadaster';
  // Bij een levering neemt de koopovereenkomst de plaats in van de
  // passeeropdracht: het is het stuk dat de transactie beschrijft. Zonder deze
  // promotie blijft het 'overig' en houdt het in de eindanalyse-prompt maar
  // 1200 tekens over — te weinig voor koopsom, waarborgsom en voorwaarden.
  // De naam van het bestand zegt te weinig (hernoemde downloads), dus dit gaat
  // op de inhoud.
  if (d.docType !== 'kadaster' && d.docType !== 'bank' && isOpdrachtStuk(d.markdown)) {
    d.docType = 'bank';
  }
}
const bronnenAanwezig = {
  passeeropdracht: docs.some((d) => d.docType === 'bank' || isOpdrachtStuk(d.markdown)),
  kadaster: docs.some((d) => d.docType === 'kadaster'),
  brp: docs.some((d) => isBrpInzage(d.markdown)),
};
// Het opdracht-stuk heet niet in elke zaaksoort hetzelfde: bij een hypotheek is
// het de passeeropdracht van de bank, bij een levering de koopovereenkomst. Met
// de hypotheek-bewoording in een leveringsdossier meldt de analyse een gemis dat
// er niet is ("de bank-passeeropdracht ontbreekt"), dus de labels volgen de
// zaaksoort. De sleutel blijft 'passeeropdracht': daar hangt de bronbewaking aan.
const OPDRACHT_LABELS = {
  hypotheek: {
    aanwezig: 'de bank-passeeropdracht',
    ontbreekt: 'de bank-passeeropdracht (er is dus geen bank, hypotheekbedrag of looptijd bekend)',
  },
  levering: {
    aanwezig: 'de koopovereenkomst of leveringsopdracht',
    ontbreekt: 'de koopovereenkomst of leveringsopdracht (er is dus niets bekend over koopsom, koper/verkoper of leveringsafspraken)',
  },
  'hypotheek+levering': {
    aanwezig: 'de koopovereenkomst en de bank-passeeropdracht',
    ontbreekt: 'de koopovereenkomst of de bank-passeeropdracht (er is dus niets bekend over koopsom, partijen, hypotheekbedrag of looptijd)',
  },
};
const opdrachtLabel = OPDRACHT_LABELS[zaaksoort] || OPDRACHT_LABELS.hypotheek;
const ONTBREEK_LABELS = {
  passeeropdracht: opdrachtLabel.ontbreekt,
  kadaster: 'de kadastrale eigendoms- of hypotheekinformatie (er is dus niets bekend over rechthebbenden, aandelen, beslagen of beperkte rechten)',
  brp: 'een BRP- of persoonsinzage',
};
const AANWEZIG_LABELS = {
  passeeropdracht: opdrachtLabel.aanwezig,
  kadaster: 'de kadastrale eigendoms- of hypotheekinformatie',
  brp: 'een BRP- of persoonsinzage',
};
const aangeleverd = Object.keys(AANWEZIG_LABELS).filter((k) => bronnenAanwezig[k]);
const ontbrekend = Object.keys(ONTBREEK_LABELS).filter((k) => !bronnenAanwezig[k]);
// Beide kanten benoemen. Alleen zeggen wat ontbreekt bleek niet genoeg: het
// model meldde "de bank heeft geen passeeropdracht aangeleverd" terwijl die
// opdracht gewoon in de prompt stond — de omgekeerde hallucinatie.
const stukkenNote =
  (aangeleverd.length
    ? 'AANGELEVERDE STUKKEN — dit dossier bevat: '
      + aangeleverd.map((k) => AANWEZIG_LABELS[k]).join('; ') + '.\n'
      + 'Meld van deze stukken niet dat ze ontbreken.\n'
    : '')
  + (ontbrekend.length
    ? 'LET OP — in dit dossier is NIET aangeleverd: '
      + ontbrekend.map((k) => ONTBREEK_LABELS[k]).join('; ') + '.\n'
      + 'Over een stuk dat niet is aangeleverd doe je geen enkele feitelijke uitspraak: je citeert er niet '
      + 'uit, je leidt er niets uit af en je noemt het niet in "bronnen". Kun je een punt alleen op zo\'n '
      + 'ontbrekend stuk baseren, laat dat punt dan weg.\n'
    : '')
  + ((aangeleverd.length || ontbrekend.length) ? '\n' : '');

const klantNaam = '';
const now = new Date();
const zaaknummer = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}_${String(now.getHours()).padStart(2, '0')}${String(now.getMinutes()).padStart(2, '0')}${String(now.getSeconds()).padStart(2, '0')}`;

// Het bank-slot bevat bij een levering de koopovereenkomst; daar hoort geen
// banknaam bij. Leeg laten, dan slaan het rapport en de webapp de regel over
// in plaats van "Bank: Onbekend (uit koopovereenkomst.docx)" te tonen.
// Bij een gecombineerd dossier zit ook de koopovereenkomst in het bank-slot;
// die hoort niet in de herkomst van de banknaam te staan.
const bankDocs = heeftHypotheek
  ? docs.filter((d) => d.docType === 'bank' && /\bpasseeropdracht\b|\bnotarisinstructie\b/i.test(d.markdown || ''))
      .map((d) => d.filename)
  : [];

// De banknaam stond hier hard op 'Onbekend', dus in de kop van élk analyse-
// rapport kwam 'Bank: Onbekend (uit passeeropdracht.pdf)' te staan — ook als de
// naam gewoon in het stuk stond. De namen komen uit registry.banks, dezelfde
// bron als de akte-flow, zodat er één lijst te onderhouden is.
// Gekozen wordt de bank die als eerste in het stuk voorkomt: de geldverstrekker
// staat in de kop, terwijl de af te lossen bank pas verderop genoemd wordt.
const bankMd = heeftHypotheek
  ? docs.filter((d) => d.docType === 'bank').map((d) => d.markdown || '').join('\n')
  : '';
let bankId = '';
let bankNaam = '';
if (bankMd) {
  let banken = {};
  try {
    banken = JSON.parse(fs.readFileSync('/data/shared/templates/registry.json', 'utf8')).banks || {};
  } catch (_) {
    // Zonder registry blijft het gedrag zoals het was: 'Onbekend'.
  }
  let vroegste = -1;
  for (const [id, bank] of Object.entries(banken)) {
    for (const kw of (bank.keywords || [])) {
      const woord = String(kw || '').trim();
      if (!woord) continue;
      // Woordgrenzen: het Rabobank-trefwoord 'ECH' zit anders in 'echtgenote'.
      const rx = new RegExp('\\b' + woord.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i');
      const m = bankMd.match(rx);
      if (m && (vroegste < 0 || m.index < vroegste)) {
        vroegste = m.index;
        bankId = id;
        bankNaam = bank.display_name || id;
      }
    }
  }
}
const bankDisplay = heeftHypotheek
  ? (bankNaam || (bankDocs.length ? `Onbekend (uit ${bankDocs.join(', ')})` : 'Onbekend'))
  : '';

return [{
  json: {
    mode: 'analyse',
    zaaksoort,
    zaaksoorten,
    docs,
    documentCount: docs.length,
    bronnen_aanwezig: bronnenAanwezig,
    stukken_note: stukkenNote,
    zaaknummer,
    bankDisplayName: bankDisplay,
    bankId,
    klantSamenvatting: klantNaam
  }
}];

// Structured-extractie voor de Object&partijen-specialist (mode=analyse).
// Haalt uit de ruwe markdown van bank + kadaster de minimale gestructureerde
// data (klanten/onderpand/kadastrale aanduiding) die de deterministische
// mismatch-checks nodig hebben. De analyse-flow kent zelf geen extractie.
const fs = require('fs');
const REGISTRY_PATH = '/data/shared/templates/registry.json';
let registry;
try { registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8')); }
catch (err) { throw new Error(`Kon templates-registry niet lezen (${REGISTRY_PATH}): ${err.message}`); }

const tmpl = String(registry.partijen_extraction_prompt || '');
if (!tmpl) throw new Error('registry.json mist partijen_extraction_prompt.');

const limits = registry.context_limits || {};
const MAX = Number(limits.specialist_partijen_analyse_combined) || 26000;
function clamp(s, max) {
  const t = String(s || '');
  return t.length <= max ? t : t.slice(0, max) + '\n…[afgekapt voor partijen-extractie]';
}

const agg = $('Aggregate Markdowns').first()?.json || {};
const docs = Array.isArray(agg.docs) ? agg.docs : [];
const bankMd = docs.filter((d) => d.docType === 'bank').map((d) => d.markdown || '').join('\n\n');
const kadMd = docs.filter((d) => d.docType === 'kadaster').map((d) => d.markdown || '').join('\n\n');
const hasBoth = Boolean(bankMd) && Boolean(kadMd);

const chatInput = hasBoth
  ? tmpl.split('{{bank_markdown}}').join(clamp(bankMd, MAX)).split('{{kadaster_markdown}}').join(clamp(kadMd, MAX))
  : 'Geen bank- én kadasterdocument beschikbaar om te vergelijken. Geef ALLEEN deze JSON terug:\n{"bank_klanten": [], "onderpand_straat": "", "onderpand_woonplaats": "", "kadaster_klanten": [], "kadastrale_gemeente": "", "kadastrale_sectie": "", "kadastrale_nummer": ""}';

return { json: { chatInput, has_both: hasBoth } };

// Parseert de structured-extractie voor de Object&partijen-specialist tot
// { partijen_extracted: {bank_klanten[], verkopers[], kopers[], kadaster_klanten[],
//   onderpand_*, kadastrale_*} }.
// LET OP: een Ollama-model met format:json levert de JSON vaak als top-level
// velden op het item (niet als string onder .text). Daarom valt de parser
// terug op de eigen keys van het node als er geen tekststring is.
function extractText(j) {
  if (!j || typeof j !== 'object') return '';
  if (typeof j.text === 'string' && j.text) return j.text;
  if (typeof j.output === 'string' && j.output) return j.output;
  if (typeof j.answer === 'string' && j.answer) return j.answer;
  if (typeof j.response === 'string' && j.response) return j.response;
  if (typeof j?.message?.content === 'string' && j.message.content) return j.message.content;
  return '';
}
function unwrapJsonLike(s) {
  let t = String(s || '').trim();
  const fence = /^```(?:json)?\s*\r?\n?([\s\S]*?)\r?\n?```$/im;
  const m = t.match(fence);
  if (m) return m[1].trim();
  if (t.startsWith('```')) t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  return t.trim();
}
function tryParse(node) {
  const raw = extractText(node).trim();
  if (raw) {
    try { return JSON.parse(unwrapJsonLike(raw)); } catch {}
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { return JSON.parse(m[0]); } catch {} }
  }
  // Fallback: JSON zit al als top-level velden op het item (format:json).
  const META = new Set(['pairedItem', 'sourceData', '$node']);
  const obj = {};
  for (const k of Object.keys(node || {})) {
    if (!META.has(k) && !k.startsWith('_')) obj[k] = node[k];
  }
  return obj;
}
function arr(x) { return Array.isArray(x) ? x : []; }
// Schoont een naam: strip alles vanaf een komma of ' geboren' (geboortedatum-
// ruis), en veelvoorkomende aanhef, zodat de achternaam-vergelijking klopt.
function cleanName(s) {
  return String((s && (s.naam ?? s)) || '')
    .split(/,| geboren /i)[0]
    .replace(/\b(mevrouw|mevr|de\s+heer|dhr|mw|hr)\b\.?/gi, '')
    .replace(/^[\s.,;-]+/, '')
