// --- Deterministische bevindingen -----------------------------------------
// Wat er in de uitdraai staat, hoeft het model niet te vinden: dat staat er
// gewoon. Twee runs op hetzelfde dossier gaven eerst drie verzonnen rechten en
// daarna niets, terwijl de kwalitatieve verplichting beide keren zwart op wit
// in het stuk stond. Die kant is dus deterministisch; de LLM mag er nuance
// bovenop leggen (bijvoorbeeld een hypotheek van een derde, of een zakelijk
// recht dat buiten dit vocabulaire valt).
const LASTEN_DUIDING = {
  'beslag': { ernst: 'kritiek', kader: 'Een beslag op het onderpand blokkeert de vestiging; de hypotheekhouder kan zijn recht niet onbezwaard krijgen (art. 3:268 BW; Rv. Boek 3).', actie: 'Stel vast of het beslag is opgeheven of vóór passeren wordt doorgehaald.' },
  'erfpacht': { ernst: 'aandacht', kader: 'Erfpacht beperkt de omvang van het te verhypothekeren recht (art. 5:85 BW e.v.); de canon- en opzeggingsvoorwaarden bepalen de zekerheidswaarde.', actie: 'Vraag de erfpachtvoorwaarden op en verwerk het recht in de onderpandomschrijving.' },
  'opstal': { ernst: 'aandacht', kader: 'Een recht van opstal splitst de eigendom van de opstallen van de grond (art. 5:101 BW e.v.).', actie: 'Vraag het vestigingsstuk op en beschrijf het recht in de akte.' },
  'vruchtgebruik': { ernst: 'aandacht', kader: 'Vruchtgebruik beperkt het genot van de hoofdgerechtigde (art. 3:201 BW e.v.); de vruchtgebruiker moet in beginsel meewerken.', actie: 'Stel vast wie vruchtgebruiker is en of medewerking nodig is.' },
  'huurbeding': { ernst: 'aandacht', kader: 'Het huurbeding (art. 3:264 BW) raakt de executiepositie van de bank.', actie: 'Controleer of het beding wordt ingeroepen en of verhuur bekend is.' },
  'kettingbeding': { ernst: 'aandacht', kader: 'Een kettingbeding gaat niet van rechtswege over en moet bij elke overdracht worden doorgegeven (art. 6:252 BW voor de kwalitatieve variant).', actie: 'Vraag het brondocument op en neem het beding op in de akte.' },
  'kwalitatieve verplichting': { ernst: 'aandacht', kader: 'Een ingeschreven kwalitatieve verplichting gaat over op de rechtsopvolger (art. 6:252 BW) en bindt de hypotheekgever.', actie: 'Vraag het brondocument op, stel de inhoud vast en beschrijf de verplichting in de akte.' },
  'erfdienstbaarheid': { ernst: 'aandacht', kader: 'Een erfdienstbaarheid rust op het perceel en gaat mee over (art. 5:70 BW e.v.).', actie: 'Vraag het vestigingsstuk op en beschrijf de erfdienstbaarheid in de akte.' },
  'voorkeursrecht': { ernst: 'aandacht', kader: 'Een gemeentelijk voorkeursrecht (Wvg) beperkt de vervreemding van het perceel.', actie: 'Stel vast of het voorkeursrecht nog geldt en of het aan vestiging in de weg staat.' },
  'publiekrechtelijke beperking': { ernst: 'aandacht', kader: 'Een ingeschreven publiekrechtelijke beperking (WKPB) kan het gebruik van het onderpand beperken.', actie: 'Vraag de beperking op bij de betreffende overheid en beoordeel de invloed op de zekerheidswaarde.' },
  'monument': { ernst: 'info', kader: 'De monumentenstatus beperkt wijzigingen aan het object (Erfgoedwet of gemeentelijke verordening).', actie: 'Vermeld de status; beoordeel of de bank hierover geïnformeerd moet worden.' },
  'exploitatiebijdrage': { ernst: 'info', kader: 'Een exploitatiebijdrage, baatbelasting of wegenfondsbijdrage kan als last op het perceel drukken.', actie: 'Stel vast of de bijdrage is voldaan of nog openstaat.' },
};

const detFindings = [];
for (const v of LASTEN_VOCABULAIRE) {
  const duiding = LASTEN_DUIDING[v.soort];
  const vp = vindplaatsen.get(v.soort);
  if (!duiding || !vp) continue;
  const herkomst = [vp.stuk ? `stuk ${vp.stuk}` : '', vp.datum ? `ingeschreven op ${vp.datum}` : '']
    .filter(Boolean).join(', ');
  detFindings.push({
    id: `lasten-${v.soort.replace(/\s+/g, '-')}`,
    ernst: duiding.ernst,
    categorie: 'Lasten en beperkingen',
    titel: v.soort.charAt(0).toUpperCase() + v.soort.slice(1),
    constatering: `Kadastrale uitdraai: "${vp.regel.slice(0, 300)}"` + (herkomst ? ` (${herkomst}).` : '.'),
    juridisch_kader: duiding.kader,
    actie: duiding.actie,
    bronnen: ['kadaster'],
  });
}

const inventarisNote = 'LET OP — in deze uitdraai komen alleen de volgende soorten letterlijk voor: '
  + aanwezigeSoorten.join(', ') + '.\n'
  + 'Beoordeel uitsluitend deze. Een soort die hier niet tussen staat, staat niet in het stuk: '
  + 'die noem je niet, ook niet om te melden dat hij ontbreekt of dat er geen zijn.\n\n';

let chatInput;
if (signalCount > 0) {
  chatInput = inventarisNote + tmpl.split('{{kadaster_markdown}}').join(kadMd);
} else {
  chatInput = 'Het bijgevoegde kadasterfragment bevat geen indicaties van beslagen, erfpacht, opstal, vruchtgebruik, huurbeding, kettingbeding, kwalitatieve verplichtingen of voorkeursrechten. Geef ALLEEN deze JSON terug, niets anders:\n{"aandachtspunten": []}';
}


// Zonder deze waarschuwing schrijft het model over stukken die niet in de
// upload zitten; de tekst komt uit 'Aggregate Markdowns' (bronnen_aanwezig).

// --- Zaaksoort-context ------------------------------------------------------
// De gebruiker kiest in de webapp om wat voor zaak het gaat; die keuze staat in
// registry.zaaksoort_context en wordt vlak vóór de INPUT-sectie van de prompt
// gezet. Daar staat hij ná alle instructies maar nog vóór de documenten, zodat
// de basisprompt zaaksoort-neutraal kan blijven en een nieuwe zaaksoort alleen
// registry-werk is.
function zaaksoortBlok(reg, soorten, sleutel) {
  const alles = (reg && reg.zaaksoort_context) || {};
  const stukken = (ctx) => [String(ctx.algemeen || ''), String((ctx.per_prompt || {})[sleutel] || '')].filter(Boolean);
  // Een combinatie heeft bij voorkeur een eigen tekst: de losse teksten
  // spreken elkaar tegen (de levering-tekst zegt dat hypotheekstukken niet
  // hoeven, wat onjuist is zodra er ook een hypotheek passeert). Staat die
  // combinatietekst er niet, dan vallen we terug op de losse teksten met een
  // kop die zegt dat beide transacties spelen.
  const sleutelvanCombinatie = soorten.join('+');
  let delen = alles[sleutelvanCombinatie] ? stukken(alles[sleutelvanCombinatie]) : [];
  if (!delen.length && soorten.length > 1) {
    delen = soorten.flatMap((s) => stukken(alles[s] || {}));
    if (delen.length) {
      delen.unshift('LET OP: dit dossier bevat meer dan één transactie (' + soorten.join(' en ')
        + '). Hieronder staat de context van elk daarvan; waar ze elkaar tegenspreken, geldt dat beide '
        + 'transacties daadwerkelijk spelen en er dus van beide stukken worden verwacht.');
    }
  }
  if (!delen.length) delen = stukken(alles[soorten[0]] || {});
  if (!delen.length) return '';
  return '=== ZAAKSOORT — CONTEXT VOOR DEZE ANALYSE ===\n' + delen.join('\n\n') + '\n\n';
}
function metZaaksoortContext(prompt, blok) {
  if (!blok) return prompt;
  const ix = String(prompt).lastIndexOf('\nINPUT:');
  if (ix < 0) return blok + prompt;
  return prompt.slice(0, ix + 1) + blok + prompt.slice(ix + 1);
}

if (signalCount > 0) {
  chatInput = metZaaksoortContext(chatInput, zaaksoortBlok(registry, zaaksoorten, 'lasten'));
  chatInput = String(aggItem.stukken_note || '') + chatInput;
}
return {
  json: {
    chatInput,
    signal_count: signalCount,
    signal_hits: hits.slice(0, 5),
    lasten_vocabulaire: vocabulaire,
    det_findings: detFindings,
    mode,
    zaaksoort,
    zaaksoorten,
    ...metaForward,
  }
};

// Parseert de output van de Lasten-en-beperkingen-specialist. Werkt zowel
// met geldige JSON via format=json als met tekst inclusief markdown-fences.
// Forceert categorie='Lasten en beperkingen' en bronnen=['kadaster'].
function extractText(j) {
  if (!j || typeof j !== 'object') return '';
  if (typeof j.text === 'string' && j.text) return j.text;
  if (typeof j.output === 'string' && j.output) return j.output;
  if (typeof j.answer === 'string' && j.answer) return j.answer;
  if (typeof j.response === 'string' && j.response) return j.response;
  if (typeof j?.message?.content === 'string' && j.message.content) return j.message.content;
  return '';
}
function unwrapJsonLike(s) {
  let t = String(s || '').trim();
  const fence = /^```(?:json)?\s*\r?\n?([\s\S]*?)\r?\n?```$/im;
  const m = t.match(fence);
  if (m) return m[1].trim();
  if (t.startsWith('```')) {
    t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  }
  return t.trim();
}
function parseSpec(node) {
  const raw = extractText(node).trim();
  if (raw) {
    try { return JSON.parse(unwrapJsonLike(raw)); } catch {}
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) {
      try { return JSON.parse(m[0]); } catch {}
    }
  }
  const META = new Set(['pairedItem', 'sourceData', '$node']);
  const obj = {};
  for (const k of Object.keys(node || {})) {
    if (!META.has(k) && !k.startsWith('_')) obj[k] = node[k];
  }
  return obj;
}

const all = $input.all();
const node = all[0]?.json || {};

// Korte-circuit: pre-filter zei geen signalen → lege array, ongeacht LLM.
let signalCount = -1;
let vocabulaire = [];
let detFindings = [];
try {
  const meta = $('Build Lasten Prompt').first()?.json;
  if (typeof meta?.signal_count === 'number') signalCount = meta.signal_count;
  if (Array.isArray(meta?.lasten_vocabulaire)) vocabulaire = meta.lasten_vocabulaire;
  if (Array.isArray(meta?.det_findings)) detFindings = meta.det_findings;
} catch (_) {}

if (signalCount === 0) {
  return [{ json: { lasten_aandachtspunten: detFindings, signal_count: 0, geweerd: [] } }];
}

let parsed = parseSpec(node);

if (!parsed || typeof parsed !== 'object') {
  parsed = { aandachtspunten: [] };
}

const WRAPPER_KEYS = new Set(['analyse', 'analysis', 'data', 'response', 'result', 'output', 'lasten']);
let depth = 0;
while (
  parsed && typeof parsed === 'object' && !Array.isArray(parsed) &&
  Object.keys(parsed).length === 1 &&
  WRAPPER_KEYS.has(Object.keys(parsed)[0]) && depth < 3
) {
  parsed = parsed[Object.keys(parsed)[0]];
  depth++;
}

const aandacht = Array.isArray(parsed.aandachtspunten) ? parsed.aandachtspunten : [];
const MAX_ITEMS = 5;
const ALLOWED = new Set(['kritiek', 'aandacht', 'info']);
const ALIASES = { critical: 'kritiek', blokkerend: 'kritiek', warning: 'aandacht', warn: 'aandacht', notice: 'info', informatief: 'info' };
const normalised = aandacht.slice(0, MAX_ITEMS).map((ap, i) => {
  const e = String(ap?.ernst || '').trim().toLowerCase();
  const ernst = ALLOWED.has(e) ? e : (ALIASES[e] || 'aandacht');
  const idRaw = String(ap?.id || '').trim();
  const id = idRaw
    ? (idRaw.startsWith('lasten-') ? idRaw : `lasten-${idRaw}`)
    : `lasten-${i + 1}`;
  return {
    id,
    ernst,
    categorie: 'Lasten en beperkingen',
    titel: String(ap?.titel || '').slice(0, 160),
    constatering: String(ap?.constatering || ''),
    juridisch_kader: String(ap?.juridisch_kader || ''),
    actie: String(ap?.actie || ''),
    bronnen: ['kadaster']
  };
});

// --- Inventarisatiefilter -------------------------------------------------
// Een punt mag alleen gaan over een soort die daadwerkelijk in de uitdraai
// staat. De prompt somt alle denkbare soorten op en dat leest als een
// menukaart: op een dossier met alleen een kwalitatieve verplichting kwamen er
// ook erfpacht, vruchtgebruik en een 'kritiek' executoriaal beslag terug. De
// inventarisatie komt uit 'Build Lasten Prompt' en is op de gestripte tekst
// gemaakt. Een punt over iets buiten dit vocabulaire (bijvoorbeeld een zakelijk
// recht uit de Belemmeringenwet) blijft staan: alleen een bekénde soort die
// aantoonbaar niet in het stuk voorkomt, gaat eruit.
const geweerd = [];
const gefilterd = normalised.filter((ap) => {
  // Bewust zónder de id: die slug verzint het model erbij en hij klopt lang
  // niet altijd. Een terecht punt over de kwalitatieve verplichting kwam terug
  // onder id 'lasten-erfpacht' en werd zo als verzinsel weggegooid. Titel,
  // constatering en kader zeggen waar het punt écht over gaat.
  const tekst = `${ap.titel} ${ap.constatering} ${ap.juridisch_kader}`;
  for (const v of vocabulaire) {
    if (v.aanwezig) continue;
    let claim;
    try { claim = new RegExp(v.claim, 'i'); } catch (_) { continue; }
    if (claim.test(tekst)) {
      geweerd.push({ id: ap.id, titel: ap.titel, soort: v.soort });
      console.warn(`[Parse Lasten JSON] punt "${ap.id}" geweerd: "${v.soort}" komt niet voor in de uitdraai`);
      return false;
    }
  }
  return true;
});

// Deterministisch eerst: die punten citeren de uitdraai zelf. Een LLM-punt over
// een soort die al deterministisch is gemeld, valt af; punten over iets anders
// (een hypotheek van een derde, een zakelijk recht buiten het vocabulaire)
// blijven staan.
const detSoorten = new Set(detFindings.map((d) => String(d.id || '')));
const aanvullend = gefilterd.filter((ap) => {
  const tekst = `${ap.titel} ${ap.constatering}`;
  for (const v of vocabulaire) {
    let claim;
    try { claim = new RegExp(v.claim, 'i'); } catch (_) { continue; }
    if (claim.test(tekst) && detSoorten.has(`lasten-${v.soort.replace(/\s+/g, '-')}`)) return false;
  }
  return true;
});
const samengevoegd = [...detFindings, ...aanvullend].slice(0, MAX_ITEMS);

return [{ json: { lasten_aandachtspunten: samengevoegd, signal_count: signalCount, geweerd } }];

// Burgerlijke-staat-specialist. Draait in mode='analyse'; input via $('Aggregate Markdowns').docs[] (geen gestructureerde extractie).
const fs = require('fs');
const REGISTRY_PATH = '/data/shared/templates/registry.json';

const mode = String($('Split Input Files').first()?.json?.mode || '').trim().toLowerCase();
const zaaksoorten = (() => {
  try {
    const v = $('Split Input Files').first()?.json?.zaaksoorten;
    return Array.isArray(v) && v.length ? v : ['hypotheek'];
  } catch (_) { return ['hypotheek']; }
})();
const zaaksoort = zaaksoorten.join('+');
const heeftLevering = zaaksoorten.includes('levering');
const heeftHypotheek = zaaksoorten.includes('hypotheek');
// Het opdracht-stuk heet per zaaksoort anders; het docType blijft 'bank'.
const OPDRACHT_DOC_LABEL = heeftLevering && heeftHypotheek
  ? 'Koopovereenkomst / passeeropdracht'
  : (heeftLevering ? 'Koopovereenkomst / leveringsopdracht' : 'Bank-passeeropdracht');

let registry;
try {
  registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8'));
} catch (err) {
  throw new Error(`Kon templates-registry niet lezen (${REGISTRY_PATH}): ${err.message}`);
}

const tmpl = String(registry.legal_specialist_prompts?.burgerlijke_staat || '');
if (!tmpl) {
  throw new Error('registry.json mist legal_specialist_prompts.burgerlijke_staat.');
}

function clamp(s, max) {
  const txt = String(s || '');
  if (txt.length <= max) return txt;
  return txt.slice(0, max) + '\n…[afgekapt voor burgerlijke-prompt]';
}

function clampKadMetDossierPrioriteit(full, max) {
  const t = String(full || '');
  if (t.length <= max) return t;
  const marker = '\n\n=== Overige dossier-PDFs';
  const ix = t.indexOf(marker);
  if (ix < 0) return clamp(t, max);
  const doss = t.slice(ix);
  let prefix = t.slice(0, ix);
  if (doss.length >= max - 96) return doss.slice(0, max - 80) + '\n…[afgekapte dossiermarkdown]';
  const headAvail = Math.max(0, max - doss.length);
  if (prefix.length > headAvail - 112) {
    prefix = prefix.slice(0, headAvail - 112) + '\n…[kadasterkern ingekort; onderstaand dossier-/BRP-deel heeft prioriteit]';
  }
  let out = prefix + doss;
  if (out.length > max) out = out.slice(0, max - 80) + '\n…[afgekapt voor burgerlijke-prompt]';
  return out;
}

const limits = (registry.context_limits || {});

const MD_PATTERNS = [
  /\bgehuwd\b/i, /\bhuwelijk/i, /huwelijksgeschiedenis/i, /partnerschapsgeschiedenis/i,
  /eerdere\s+huwelijk/i, /eerdere\s+relatie/i, /ontbonden\s+huwelijk/i,
  /betrekking\s+tot\s+het\s+huwelijk/i, /vorige\s+echtgen/i,
  /\b(weduwe|weduwnaar)\b/i, /\bpartnerschap\b/i, /\bgeregistreerd\s+partn/i,
  /\becht(?:genoot|genote)\b/i, /gemeen(?:schap)?\s+van\s+goederen/i,
  /huwelijkse\s+voorwaarden/i, /\bsamenleving(?:scontract)?\b/i,
  /\b(gescheiden|echtscheid|scheiding|ontbinding\s+huwelijk)\b/i,
  /beëindigd\s+geregistreerd\s+partnerschap/i, /\bex[- ]?(echtgenoot|partner)\b/i,
  /\bboedelverdeling\b/i, /\bverdeling\b/i, /\bonverdeeld[e]?\b/i, /\bmede-eigenaar\b/i,
  /\bBRP\b/i, /\bBasisregistratie\s+Personen\b/i,
  /personenlijst|gezinssamenstelling|burgerlijke\s+staat/i,
  /huwel(?:ijk)?(?:s|\s|\n)*geschiedenis/i,
  /geschiedenis(?:\s|\n)*(?:van\s|\n)*(?:het\s)?huwelijks?(?:gemeensch)?/i,
  /datum\s+huwelijk|datum.*ontbind/i,
  /\binschrijving\b.*\b(gemeente|burgerlijke\s+staat)\b/i,
  /Overige\s+dossier-PDFs/i,
];

let chatInput, signalCount, mdHits, rechtsbronnen = [], structuredHits = 0, moreOwnersThanDebtors = 0;
let klantenCount = 0, kadKlantenCount = 0;
let metaForward = {};

const aggItem = $('Aggregate Markdowns').first()?.json || {};
const docs = Array.isArray(aggItem.docs) ? aggItem.docs : [];
const MAX_MD_ANALYSE = Number(limits.specialist_burgerlijke_analyse_combined) || 26000;
const allMdFull = docs.map((d, i) => {
  const label = d.docType === 'bank' ? OPDRACHT_DOC_LABEL
    : d.docType === 'kadaster' ? 'Kadaster eigendomsinformatie'
    : 'Overig dossier-stuk';
  return `=== DOCUMENT ${i + 1} — ${label} — ${d.filename || `document_${i + 1}`} ===\n${d.markdown || ''}`;
}).join('\n\n');
const combinedMd = clamp(allMdFull, MAX_MD_ANALYSE);

mdHits = [];
for (const re of MD_PATTERNS) {
  const m = allMdFull.match(re);
  if (m) mdHits.push(m[0]);
}
signalCount = mdHits.length;

// --- Overlijden is geen echtscheiding ---------------------------------------
// De prompt zegt dit al (regel 8), maar het 7B-model trapte er toch in: het
// noemde de overleden echtgenote 'de ex-partner' en maakte er 'echtscheiding
// zonder verdeling' van, met een verzonnen artikel erbij. Een korte, harde
// notitie bovenaan werkt beter dan een regel diep in de instructies — dat is
// ook de reden dat stukken_note daar staat.
const OVERLIJDEN_RX = /\boverleden\b|reden\s+ontbinding[^\n]{0,60}overl(?:ijden|eden)|\b(?:weduwe|weduwnaar)\b/i;
const overlijdenSignaal = OVERLIJDEN_RX.test(allMdFull);
const feitenNote =
  (overlijdenSignaal
    ? 'LET OP — FEIT: in dit dossier is een huwelijk of partnerschap geëindigd door OVERLIJDEN. Dat is GEEN '
      + 'echtscheiding. Gebruik de woorden "echtscheiding", "gescheiden", "scheiding" of "ex-partner" niet; de '
      + 'betrokkene is weduwe of weduwnaar. De afwikkeling van de nalatenschap (verklaring van erfrecht, '
      + 'verdeling, erfgenamen als mede-eigenaar) hoort bij een andere specialist en laat je hier weg.\n'
    : '')
  + 'LET OP — de "Burgerlijke staat" in een kadastrale uitdraai hoort bij de verkrijging van destijds, niet bij '
  + 'vandaag; het kadaster kent de staat "overleden" niet. Staat daar "Gehuwd" terwijl de passeeropdracht een '
  + 'andere staat meldt, dan is dat geen tegenstrijdigheid en dus geen aandachtspunt.\n\n';

if (signalCount > 0) {
  chatInput = tmpl
    .split('{{klanten_json}}').join('[]')
    .split('{{kadaster_klanten_json}}').join('[]')
    .split('{{bank_markdown}}').join(combinedMd)
    .split('{{kadaster_markdown}}').join('(alle aangeleverde stukken \u2014 bank, kadaster en inzage \u2014 staan hierboven in het gecombineerde blok)');

    // --- RAG: relevante rechtsbronnen ophalen uit de kennisbank (Qdrant) ---
    try {
      const queryText = 'Burgerlijke staat en huwelijksvermogensrecht bij een hypotheekakte: toestemming echtgenoot of geregistreerd partner (art. 1:88 BW), verdeling na echtscheiding, mede-eigendom. Signalen in dossier: ' + (mdHits || []).slice(0, 8).join(', ');
      const emb = await this.helpers.httpRequest({ method: 'POST', url: 'http://host.docker.internal:11434/api/embeddings', body: { model: 'nomic-embed-text', prompt: queryText }, json: true, timeout: 20000 });
      const vector = emb && emb.embedding;
      if (vector) {
        const sr = await this.helpers.httpRequest({ method: 'POST', url: 'http://qdrant:6333/collections/juridische_bronnen/points/search', body: { vector, limit: 3, with_payload: true }, json: true, timeout: 20000 });
        rechtsbronnen = ((sr && sr.result) || []).map((h) => ({ artikel: String((h.payload && h.payload.artikel) || ''), titel: String((h.payload && h.payload.titel) || ''), bron: String((h.payload && h.payload.bron) || ''), url: String((h.payload && h.payload.url) || ''), tekst: String((h.payload && h.payload.tekst) || ''), score: Math.round((h.score || 0) * 1000) / 1000 }));
      }
