  if (!Array.isArray(bron)) return ['passeeropdracht'];
  const out = [];
  for (const b of bron) {
    const k = String(b).toLowerCase().trim().replace(/\s+/g, '');
    const mapped = ALIASES[k] || (ALLOWED.has(k) ? k : null);
    if (mapped && !out.includes(mapped)) out.push(mapped);
