      .map((l) => brpVeld(sectie, l)).filter(Boolean).join(' ').trim();
    if (!soortRuw && !partner && !datum) continue;
    return {
      soort: /partnerschap/i.test(soortRuw) ? 'geregistreerd partnerschap' : 'huwelijk',
