const kadUitAnker = leesGerechtigden(kadMdFull);
const kadKlanten = kadUitAnker.length
  ? kadUitAnker
  : (Array.isArray(extracted.kadaster_klanten) ? extracted.kadaster_klanten : []);

// --- deterministische checks (overgenomen uit Deterministic Checks, akte-flow) ---
function stripAccents(s) { return String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, ''); }
function normName(s) { return stripAccents(s).toLowerCase().replace(/[^a-z]/g, ''); }
function normWord(s) { return stripAccents(s).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function lastSurnameToken(s) {
  const cleaned = String(s || '').replace(/[,.;]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!cleaned) return '';
  const parts = cleaned.split(' ').filter(Boolean);
  return normName(parts[parts.length - 1] || '');
}

const detFindings = [];
// De naam- en tellingchecks hieronder gaan uit van één premisse: de cliënt uit
// het opdracht-stuk hoort de rechthebbende in het kadaster te zijn. Bij een
// hypotheek klopt dat; bij een levering niet — daar is de KOPER cliënt en de
// VERKOPER rechthebbende, dus levert elke vergelijking per positie een vals
// alarm op ("achternaam cliënt 1 verschilt": koper vs. verkoper). Bij een
// levering laten we het rollenonderscheid daarom over aan de specialist-LLM,
// die via de zaaksoort-context weet dat alleen de verkoper hoeft te matchen.
// De objectcheck verderop blijft wel staan: het perceel moet in beide stukken
// hetzelfde zijn, ongeacht de zaaksoort.
// Met rollen uit de koopovereenkomst is de vergelijking wél te maken: de
// VERKOPER hoort in het kadaster te staan, de KOPER bij de bank. Zonder rollen
// (een zuivere hypotheekzaak) blijft de oude vergelijking per positie gelden;
// bij een levering zonder herkende rollen wordt er niets vergeleken, want dan
// zou koper tegen verkoper worden gelegd.
const rollenBekend = verkopers.length > 0 || kopers.length > 0;
const vergelijkPartijen = !heeftLevering && !rollenBekend;
if (vergelijkPartijen && bankKlanten.length > 0 && kadKlanten.length > 0 && bankKlanten.length !== kadKlanten.length) {
  detFindings.push({
    id: 'partijen-klantentelling-mismatch', ernst: 'kritiek', categorie: 'Object en partijen',
    titel: 'Aantal cliënten wijkt af van aantal rechthebbenden',
    constatering: `Passeeropdracht noemt ${bankKlanten.length} cliënt(en); Kadaster vermeldt ${kadKlanten.length} rechthebbende(n).`,
    juridisch_kader: 'Schuldenaren in de hypotheekakte moeten in beginsel gelijk zijn aan de rechthebbenden op het onderpand. Afwijking duidt op (gelijktijdige) overdracht, vererving of een ontbrekende partij.',
    actie: 'Verifieer of een eigendomsoverdracht gelijktijdig passeert, of dat een rechthebbende ontbreekt in een van de stukken.',
    bronnen: ['passeeropdracht', 'kadaster']
  });
}
const pairs = vergelijkPartijen ? Math.min(bankKlanten.length, kadKlanten.length) : 0;
for (let i = 0; i < pairs; i++) {
  const bRaw = String(bankKlanten[i]?.naam || '');
  const kRaw = String(kadKlanten[i]?.naam || '');
  const bLast = lastSurnameToken(bRaw);
  const kLast = lastSurnameToken(kRaw);
  if (!bLast || !kLast) continue;
  if (bLast === kLast) continue;
  if (bLast.includes(kLast) || kLast.includes(bLast)) continue;
  detFindings.push({
    id: `partijen-naam-mismatch-${i + 1}`, ernst: 'kritiek', categorie: 'Object en partijen',
    titel: `Achternaam cliënt ${i + 1} verschilt tussen bank en kadaster`,
    constatering: `Passeeropdracht: "${bRaw}". Kadaster: "${kRaw}". Achternamen komen niet overeen.`,
    juridisch_kader: 'De rechthebbende op het onderpand moet de hypotheek vestigen. Naamverschil kan duiden op naamswijziging, vererving of een geplande eigendomsoverdracht.',
    actie: 'Vergelijk met BRP/legitimatie; vraag indien nodig verklaring van erfrecht, koopakte of huwelijksakte op.',
    bronnen: ['passeeropdracht', 'kadaster']
  });
}
// --- Deterministische objectvergelijking ------------------------------------
// Adres en kadastrale aanduiding worden uit de ruwe markdown gelezen en
// genormaliseerd vergeleken, in plaats van dat het model twee schrijfwijzen
// naast elkaar legt. Dat laatste ging mis: "Woonhuis, Twee onder een kap,
// Oudendijk 14, 4223 NL te Hoornaar" tegenover "Oudendijk 14 4223 NL Hoornaar"
// leverde een KRITIEK "afwijkende kadastrale aanduiding" op, terwijl het
// hetzelfde pand is.
function plat(s) {
  return String(s || '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

/** Kadastrale aanduidingen: {gemeente, sectie, nummer} in beide schrijfwijzen. */
function leesAanduidingen(md) {
  const t = String(md || '');
  const uit = [];
  const voegToe = (g, s, n) => {
    const rec = { gemeente: String(g).trim(), sectie: String(s).trim().toUpperCase(), nummer: String(n).trim().replace(/^0+/, '') };
    const sleutel = plat(rec.gemeente) + '|' + plat(rec.sectie) + '|' + rec.nummer;
    if (rec.gemeente && rec.sectie && rec.nummer && !uit.some((x) => x._sleutel === sleutel)) {
      uit.push({ ...rec, _sleutel: sleutel });
    }
  };
  // "kadastraal bekend gemeente Hoornaar, sectie A, nummer 291"
  const rxLang = /gemeente\s+([A-Za-zÀ-ÿ'’\-\. ]{2,40}?)\s*[,;]?\s*sectie\s+([A-Za-z]{1,3})\s*[,;]?\s*(?:nummer|nr\.?|no\.?)\s*(\d{1,6})/gi;
  // "Kadastrale aanduiding | Hoornaar A 291"
  const rxKort = /Kadastrale\s+aanduiding\s*\|?\s*([A-Za-zÀ-ÿ'’\-\. ]{2,40}?)\s+([A-Z]{1,3})\s+(\d{1,6})/gi;
  let m;
  while ((m = rxLang.exec(t))) voegToe(m[1], m[2], m[3]);
  while ((m = rxKort.exec(t))) voegToe(m[1], m[2], m[3]);
  return uit;
}

/** Adressen, geankerd op de postcode; wat ervóór staat aan omschrijving telt niet mee. */
function leesAdressen(md) {
  const t = String(md || '');
  const uit = [];
  const rx = /(\d{4})\s?([A-Za-z]{2})\b/g;
  let m;
  while ((m = rx.exec(t))) {
    const voor = t.slice(Math.max(0, m.index - 90), m.index);
    const straatM = voor.match(/([A-Za-zÀ-ÿ'’\.\-]+(?:\s+[A-Za-zÀ-ÿ'’\.\-]+){0,3}\s+\d{1,5}\s?[a-zA-Z]?)\s*,?\s*$/);
    if (!straatM) continue;
    const na = t.slice(m.index + m[0].length, m.index + m[0].length + 60);
    const plaatsM = na.match(/^[\s,]*(?:te\s+)?([A-Za-zÀ-ÿ'’\-]+(?:\s+[A-Za-zÀ-ÿ'’\-]+){0,2})/);
    // Inleidende woorden ('wonende', 'plaatselijk bekend') horen niet bij de
    // straatnaam; ze staan er in de stukken standaard voor.
    const straat = straatM[1].replace(/\s+/g, ' ').trim()
      .replace(/^(?:wonende|woonachtig|adres|gelegen|plaatselijk\s+bekend|bekend|te|het\s+verkochte|onderpand)\s+/i, '')
      .trim();
    const postcode = `${m[1]} ${m[2].toUpperCase()}`;
    // De plaatsnaam loopt in kadasteruitdraaien door in de toelichting
    // ('Hoornaar Locatiegegevens zijn ontleend aan …'); daar kappen we hem af.
    const plaats = plaatsM
      ? plaatsM[1].replace(/\s+/g, ' ').trim()
          .replace(/\s+(?:Locatiegegevens|Verblijfsobject|Kadastrale|Persoonsgegevens|Basisregistratie|is|zijn|Deze|Nederland)\b.*$/i, '')
          .trim()
      : '';
    const nummer = (straat.match(/(\d{1,5}\s?[a-zA-Z]?)$/) || [])[1] || '';
    const sleutel = plat(straat) + '|' + plat(postcode);
    if (!uit.some((x) => x._sleutel === sleutel)) {
      uit.push({ straat, postcode, plaats, nummer, _sleutel: sleutel, _nummer: plat(nummer), _pc: plat(postcode), _plaats: plat(plaats) });
    }
  }
  return uit;
}

function zelfdeAdres(a, b) {
  if (a._pc && b._pc && a._nummer && b._nummer) return a._pc === b._pc && a._nummer === b._nummer;
  return a._sleutel === b._sleutel || (plat(a.straat) === plat(b.straat) && a._plaats === b._plaats);
}

function vergelijkObject(kadMd, opdrMd, opdrachtLabel) {
  const uit = [];
  const kadAand = leesAanduidingen(kadMd);
  const opdrAand = leesAanduidingen(opdrMd);
  const toon = (a) => `${a.gemeente} ${a.sectie} ${a.nummer}`;

  if (kadAand.length && opdrAand.length) {
    const overlap = opdrAand.some((o) => kadAand.some((k) => k._sleutel === o._sleutel));
    if (!overlap) {
      uit.push({
        id: 'partijen-object-aanduiding-mismatch', ernst: 'kritiek', categorie: 'Object en partijen',
        titel: 'Kadastrale aanduiding wijkt af',
        constatering: `${opdrachtLabel}: ${opdrAand.map(toon).join('; ')}. Kadastrale eigendomsinformatie: ${kadAand.map(toon).join('; ')}.`,
        juridisch_kader: 'De akte moet het perceel ondubbelzinnig aanduiden; een andere gemeente, sectie of nummer betekent een ander object.',
        actie: 'Stel vast welk perceel wordt bedoeld en laat de afwijkende aanduiding corrigeren vóór het passeren.',
        bronnen: ['passeeropdracht', 'kadaster'],
      });
    }
    return uit; // de aanduiding is beslissend; adresverschillen zijn dan schrijfwijze
  }

  const kadAdr = leesAdressen(kadMd);
  const opdrAdr = leesAdressen(opdrMd);
  if (kadAdr.length && opdrAdr.length) {
    const overlap = kadAdr.some((k) => opdrAdr.some((o) => zelfdeAdres(k, o)));
    if (!overlap) {
      uit.push({
        id: 'partijen-object-adres-mismatch', ernst: 'aandacht', categorie: 'Object en partijen',
        titel: 'Adres van het onderpand komt niet voor in het opdracht-stuk',
        constatering: `Kadastrale eigendomsinformatie: ${kadAdr.map((a) => `${a.straat}, ${a.postcode} ${a.plaats}`.trim()).join('; ')}. ${opdrachtLabel}: ${opdrAdr.map((a) => `${a.straat}, ${a.postcode} ${a.plaats}`.trim()).join('; ')}.`,
        juridisch_kader: 'Het object in de akte moet hetzelfde zijn als het perceel uit de eigendomsinformatie.',
        actie: 'Controleer of beide stukken hetzelfde pand betreffen; let op een afwijkende schrijfwijze vóór je uitgaat van een ander object.',
        bronnen: ['passeeropdracht', 'kadaster'],
      });
    }
  }
  return uit;
}

// --- rolgebonden partijencontrole -----------------------------------------
function naamMatch(a, b) {
  const x = lastSurnameToken(a), y = lastSurnameToken(b);
  if (!x || !y) return false;
  return x === y || x.includes(y) || y.includes(x);
}
function naamLijst(x) { return x.map((k) => String(k?.naam || '').trim()).filter(Boolean); }

if (verkopers.length && kadKlanten.length) {
  const kadNamen = naamLijst(kadKlanten);
  const missend = naamLijst(verkopers).filter((v) => !kadNamen.some((k) => naamMatch(v, k)));
  if (missend.length) {
    detFindings.push({
      id: 'partijen-verkoper-niet-rechthebbende', ernst: 'kritiek', categorie: 'Object en partijen',
      titel: 'Verkoper komt niet voor als rechthebbende',
      constatering: 'Verkoper volgens de koopovereenkomst: ' + missend.join(', ')
        + '. Rechthebbende(n) volgens de kadastrale eigendomsinformatie: ' + kadNamen.join(', ') + '.',
      juridisch_kader: 'Alleen de rechthebbende kan het goed overdragen (art. 3:84 BW). Staat de verkoper niet als rechthebbende geregistreerd, dan is zijn beschikkingsbevoegdheid niet vastgesteld.',
      actie: 'Ga na of het om een naamsvariant gaat of om een andere partij; vraag zo nodig de titelketen, een verklaring van erfrecht of een akte van verdeling op.',
      bronnen: ['passeeropdracht', 'kadaster']
    });
  } else if (naamLijst(verkopers).length !== kadNamen.length) {
    detFindings.push({
      id: 'partijen-verkopers-aantal', ernst: 'aandacht', categorie: 'Object en partijen',
      titel: 'Aantal verkopers wijkt af van het aantal rechthebbenden',
      constatering: 'Koopovereenkomst noemt ' + naamLijst(verkopers).length + ' verkoper(s): ' + naamLijst(verkopers).join(', ')
        + '. Kadaster vermeldt ' + kadNamen.length + ' rechthebbende(n): ' + kadNamen.join(', ') + '.',
      juridisch_kader: 'Alle deelgenoten moeten aan de levering meewerken; ontbreekt er een, dan is de overdracht niet compleet.',
      actie: 'Controleer of alle rechthebbenden partij zijn bij de koopovereenkomst en bij de akte.',
      bronnen: ['passeeropdracht', 'kadaster']
    });
  }
}

if (kopers.length && bankKlanten.length && heeftLevering && heeftHypotheek) {
  const bankNamen = naamLijst(bankKlanten);
  const missend = naamLijst(kopers).filter((k) => !bankNamen.some((b) => naamMatch(k, b)));
  if (missend.length) {
    detFindings.push({
      id: 'partijen-koper-niet-clientvan-bank', ernst: 'aandacht', categorie: 'Object en partijen',
      titel: 'Koper komt niet voor als cliënt in de passeeropdracht',
      constatering: 'Koper volgens de koopovereenkomst: ' + missend.join(', ')
        + '. Cliënt(en) volgens de passeeropdracht: ' + bankNamen.join(', ') + '.',
      juridisch_kader: 'De koper wordt bij de levering eigenaar en vestigt daarna de hypotheek; hij hoort dus ook de hypotheekgever in de passeeropdracht te zijn.',
      actie: 'Controleer of koper en hypotheekgever dezelfde partij zijn en of de bank van de juiste verkrijger uitgaat.',
      bronnen: ['passeeropdracht']
    });
  }
}

// Objectvergelijking op de ruwe markdown; vervangt de oude check op
// woonplaats-vs-kadastrale-gemeente, die op de LLM-extractie leunde en alleen
// de gemeente zag.
detFindings.push(...vergelijkObject(kadMdFull, bankMdFull, OPDRACHT_DOC_LABEL));

// --- LLM-prompt (nuance); alleen als bank + kadaster beide aanwezig ---
const onderpand = { straat: extracted.onderpand_straat || null, woonplaats: extracted.onderpand_woonplaats || null };
const kadObject = { gemeente: extracted.kadastrale_gemeente || null, sectie: extracted.kadastrale_sectie || null, nummer: extracted.kadastrale_nummer || null };

// Wat de code zelf uit de stukken heeft gelezen gaat als vaststaand mee, zodat
// het model niet nog eens twee schrijfwijzen naast elkaar gaat leggen.
const objectFeiten = (() => {
  const kadA = leesAanduidingen(kadMdFull), opdrA = leesAanduidingen(bankMdFull);
  const kadAdr = leesAdressen(kadMdFull), opdrAdr = leesAdressen(bankMdFull);
  const toonA = (x) => x.map((a) => a.gemeente + ' ' + a.sectie + ' ' + a.nummer).join('; ') || '(niet gevonden)';
  const toonAdr = (x) => x.map((a) => (a.straat + ', ' + a.postcode + ' ' + a.plaats).trim()).join('; ') || '(niet gevonden)';
  return '=== OBJECT — DETERMINISTISCH GELEZEN (deze vergelijking is al in code gedaan) ===\n'
    + 'Kadastrale aanduiding volgens ' + OPDRACHT_DOC_LABEL + ': ' + toonA(opdrA) + '\n'
    + 'Kadastrale aanduiding volgens de eigendomsinformatie: ' + toonA(kadA) + '\n'
    + 'Adres volgens ' + OPDRACHT_DOC_LABEL + ': ' + toonAdr(opdrAdr) + '\n'
    + 'Adres volgens de eigendomsinformatie: ' + toonAdr(kadAdr) + '\n'
    + 'De vergelijking van adres en kadastrale aanduiding is hierboven al gemaakt en wordt apart gerapporteerd. '
    + 'Doe die NIET over: meld geen afwijkend object, adres of kadastrale aanduiding. Een andere schrijfwijze '
    + '(een omschrijving als "Woonhuis, twee onder een kap" ervoor, hoofdletters, wel of geen spatie in de '
    + 'postcode) is geen verschil. Beoordeel uitsluitend de PARTIJEN en hun rollen.\n\n';
})();
const hasBoth = Boolean(bankMdFull) && Boolean(kadMdFull);
// De drie onderwerpen die deze specialist had — partijen, aantallen en het
// object — worden nu alle drie in code getoetst (hierboven). De LLM-aanroep
// voegde daar niets meer aan toe en leverde structureel valse kritieke punten
// op: twee schrijfwijzen van hetzelfde pand, en cliënten die 'niet in het
// kadaster stonden' terwijl ze er wel in staan. signalCount 0 stuurt de IF
// langs de chain heen; alleen de deterministische bevindingen gaan door.
// Terugzetten = hier weer `hasBoth ? 1 : 0` en in Parse Partijen JSON de
// onderwerpen weer vrijgeven.
const signalCount = 0;
const llmOvergeslagen = hasBoth;

let chatInput;
if (signalCount > 0) {
  chatInput = tmpl
    .split('{{klanten_json}}').join(JSON.stringify(bankKlanten, null, 2))
    .split('{{kadaster_klanten_json}}').join(JSON.stringify(kadKlanten, null, 2))
    .split('{{onderpand_json}}').join(JSON.stringify(onderpand, null, 2))
    .split('{{kadaster_object_json}}').join(JSON.stringify(kadObject, null, 2))
    .split('{{bank_markdown}}').join(clamp(bankMdFull, MAX_BANK))
    .split('{{kadaster_markdown}}').join(clamp(kadMdFull, MAX_KAD));
} else {
  chatInput = 'Geen bank- én kadasterdocument beschikbaar om cliënten/object te vergelijken. Geef ALLEEN deze JSON terug, niets anders:\n{"aandachtspunten": []}';
}


// Zonder deze waarschuwing schrijft het model over stukken die niet in de
// upload zitten; de tekst komt uit 'Aggregate Markdowns' (bronnen_aanwezig).

// --- Zaaksoort-context ------------------------------------------------------
// De gebruiker kiest in de webapp om wat voor zaak het gaat; die keuze staat in
// registry.zaaksoort_context en wordt vlak vóór de INPUT-sectie van de prompt
// gezet. Daar staat hij ná alle instructies maar nog vóór de documenten, zodat
// de basisprompt zaaksoort-neutraal kan blijven en een nieuwe zaaksoort alleen
// registry-werk is.
function zaaksoortBlok(reg, soorten, sleutel) {
  const alles = (reg && reg.zaaksoort_context) || {};
  const stukken = (ctx) => [String(ctx.algemeen || ''), String((ctx.per_prompt || {})[sleutel] || '')].filter(Boolean);
  // Een combinatie heeft bij voorkeur een eigen tekst: de losse teksten
  // spreken elkaar tegen (de levering-tekst zegt dat hypotheekstukken niet
  // hoeven, wat onjuist is zodra er ook een hypotheek passeert). Staat die
  // combinatietekst er niet, dan vallen we terug op de losse teksten met een
  // kop die zegt dat beide transacties spelen.
  const sleutelvanCombinatie = soorten.join('+');
  let delen = alles[sleutelvanCombinatie] ? stukken(alles[sleutelvanCombinatie]) : [];
  if (!delen.length && soorten.length > 1) {
    delen = soorten.flatMap((s) => stukken(alles[s] || {}));
    if (delen.length) {
      delen.unshift('LET OP: dit dossier bevat meer dan één transactie (' + soorten.join(' en ')
        + '). Hieronder staat de context van elk daarvan; waar ze elkaar tegenspreken, geldt dat beide '
        + 'transacties daadwerkelijk spelen en er dus van beide stukken worden verwacht.');
    }
  }
  if (!delen.length) delen = stukken(alles[soorten[0]] || {});
  if (!delen.length) return '';
  return '=== ZAAKSOORT — CONTEXT VOOR DEZE ANALYSE ===\n' + delen.join('\n\n') + '\n\n';
}
function metZaaksoortContext(prompt, blok) {
  if (!blok) return prompt;
  const ix = String(prompt).lastIndexOf('\nINPUT:');
  if (ix < 0) return blok + prompt;
  return prompt.slice(0, ix + 1) + blok + prompt.slice(ix + 1);
}

if (signalCount > 0) {
  chatInput = metZaaksoortContext(chatInput, zaaksoortBlok(registry, zaaksoorten, 'object_partijen'));
  chatInput = metZaaksoortContext(chatInput, objectFeiten);
  chatInput = String(agg.stukken_note || '') + chatInput;
}
return {
  json: {
    chatInput,
    signal_count: signalCount,
    llm_overgeslagen: llmOvergeslagen,
    det_findings: detFindings,
    verkopers_count: verkopers.length,
    kopers_count: kopers.length,
    kadaster_uit_anker: kadUitAnker.length,
    bank_klanten_count: bankKlanten.length,
    kadaster_klanten_count: kadKlanten.length,
    mode,
    zaaksoort,
    zaaksoorten,
    bankDisplayName: agg.bankDisplayName || '',
    zaaknummer: agg.zaaknummer || '',
  }
};

// Parseert de LLM-output van de Object&partijen-specialist en voegt die samen
// met de deterministische bevindingen (det_findings uit Build Partijen Prompt).
// De deterministische bevindingen verschijnen ALTIJD (harde feiten); de
// LLM-bevindingen alleen wanneer de LLM draaide. Per onderwerp wint de
// deterministische bevinding, zodat er geen dubbele aandachtspunten ontstaan.
function extractText(j) {
  if (!j || typeof j !== 'object') return '';
  if (typeof j.text === 'string' && j.text) return j.text;
  if (typeof j.output === 'string' && j.output) return j.output;
  if (typeof j.answer === 'string' && j.answer) return j.answer;
  if (typeof j.response === 'string' && j.response) return j.response;
  if (typeof j?.message?.content === 'string' && j.message.content) return j.message.content;
  return '';
}
function unwrapJsonLike(s) {
  let t = String(s || '').trim();
  const fence = /^```(?:json)?\s*\r?\n?([\s\S]*?)\r?\n?```$/im;
  const m = t.match(fence);
  if (m) return m[1].trim();
  if (t.startsWith('```')) t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  return t.trim();
}
function parseSpec(node) {
  const raw = extractText(node).trim();
  if (raw) {
    try { return JSON.parse(unwrapJsonLike(raw)); } catch {}
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { return JSON.parse(m[0]); } catch {} }
  }
