const vererving = reportFor('vererving', 'vererving', 'Parse Vererving JSON');
const lasten = reportFor('lasten', 'lasten', 'Parse Lasten JSON');
const burgerlijke = reportFor('burgerlijke', 'burgerlijke', 'Parse Burgerlijke JSON');
