    if (b.koopsom !== null && b.waarborgsom !== null) {
      const pct = (b.waarborgsom / b.koopsom) * 100;
      if (Math.abs(pct - 10) > 0.5) {
        uit.push(punt('bedragen-waarborgsom-afwijkend', 'aandacht', 'Waarborgsom wijkt af van de gebruikelijke 10%',
          `Koopsom ${euro(b.koopsom)}, waarborgsom ${euro(b.waarborgsom)} — dat is ${pct.toFixed(1)}% van de koopsom.`,
          'Controleer welk percentage in de koopovereenkomst is afgesproken en of het gestorte bedrag daarmee klopt.'));
      }
    }
    if (b.koopsom !== null && b.waarborgsom === null && !b.bankgarantie_genoemd) {
      uit.push(punt('bedragen-geen-waarborgsom', 'aandacht', 'Geen waarborgsom of bankgarantie gevonden',
        `Er is een koopsom van ${euro(b.koopsom)} gevonden, maar geen waarborgsom en geen bankgarantie.`,
        'Ga na of partijen een waarborgsom of bankgarantie zijn overeengekomen en of die is gesteld.'));
    }
    if (b.koopsom === null) {
      uit.push(punt('bedragen-geen-koopsom', 'aandacht', 'Koopsom niet vastgesteld',
        'In het aangeleverde opdracht-stuk is geen koopsom op een herkenbare plaats gevonden.',
