  if (b.leningbedrag !== null && b.inschrijving_totaal !== null && b.inschrijving_totaal < b.leningbedrag) {
    uit.push(punt('bedragen-inschrijving-lager-dan-lening', 'kritiek', 'Inschrijvingsbedrag lager dan het leningbedrag',
