// en waarborgsom uit de koopovereenkomst, hoofdsom en inschrijving uit de
// passeeropdracht. De velden overlappen niet, dus ze kunnen naast elkaar in één
// object; elke zaaksoort levert zijn eigen controles.
const bedragen = opdrachtMd
  ? zaaksoorten.reduce((acc, s) => Object.assign(acc, leesBedragen(opdrachtMd, s)), {})
  : null;
const bedragenFindings = bedragen
  ? zaaksoorten.flatMap((s) => controleerBedragen(bedragen, s))
  : [];

function bedragenBlok(b, soorten) {
  if (!b) return '';
  const perSoort = {
    levering: [['Koopsom', b.koopsom], ['Waarborgsom', b.waarborgsom], ['Roerende zaken', b.roerende_zaken],
               ['Financieringsvoorbehoud (hoofdsom)', b.financiering]],
    hypotheek: [['Leningbedrag', b.leningbedrag], ['Inschrijvingsbedrag (totaal)', b.inschrijving_totaal],
