function zaaksoortBlok(reg, soorten, sleutel) {
  const alles = (reg && reg.zaaksoort_context) || {};
  const stukken = (ctx) => [String(ctx.algemeen || ''), String((ctx.per_prompt || {})[sleutel] || '')].filter(Boolean);
  // Zie de specialist-prompts: een combinatie krijgt bij voorkeur haar eigen
  // tekst, omdat de losse teksten elkaar tegenspreken.
  const sleutelvanCombinatie = soorten.join('+');
