const chatInput = metZaaksoortContext(basePrompt, zaaksoortBlok(registry, zaaksoorten, 'flex'))
  .split('{{bank_markdown}}').join(bedragenBlok(bedragen, zaaksoorten) + clamp(geenBankNote + blocks, MAX_TOTAL))
  .split('{{kadaster_markdown}}').join('(zie documentfragmenten hierboven)')
  .split('{{extracted_json}}').join('(geen gestructureerde extractie in deze analyse-only-flow)');

return [{
  json: {
    chatInput,
    mode: 'analyse',
    zaaksoort,
    zaaksoorten,
    bedragen,
    bedragen_findings: bedragenFindings,
    // Elk bedrag dat ergens in de stukken staat; hiermee wordt verderop
    // gecontroleerd of de LLM geen bedrag noemt dat nergens voorkomt.
    bedragen_in_stukken: Array.from(new Set(
      docs.flatMap((d) => {
        const uit = [];
        const rx = new RegExp(BEDRAG_RX, 'gi');
        let m;
        while ((m = rx.exec(String(d.markdown || '')))) { const x = centen(m[1]); if (x !== null) uit.push(x); }
