});

// --- Geen verzonnen recht in Bedragen/Documentatie -------------------------
// De flex-chain is de enige LLM in deze keten zonder kennisbank: de vier
// specialisten krijgen echte artikeltekst mee, deze niet. Zonder bron verzint
// een 7B-model wetten die niet bestaan — waargenomen: "Wet Koopverkoop en
// Huurverlening" en "Wet Hypotheekrecht (WetHR)", allebei niet bestaand, in
// het juridisch kader van een punt over een bedrag. De prompt verbiedt
// verwijzingen nu, maar dat is bij dit model geen garantie; deze filter wel.
// Alleen de flex-punten (Bedragen, Documentatie, Overig) gaan er doorheen —
// bij de specialisten IS het artikel het punt, en dat is er een uit de
// kennisbank.
const WETSVERWIJZING_RX = /\bart(?:\.|ikel)\s*\d|\b\d+:\d+\s*BW\b|\bBW\b|\bBoek\s+\d\b|\bWet\s+(?:op\s+|ter\s+|inzake\s+)?[A-Z]|\(Wet[A-Za-z]*\)|\bWetboek\b|\bRv\b|\bWwft\b|\bWna\b|\bWBR\b/;
function zonderWetsverwijzing(tekst) {
  const zinnen = String(tekst || '').split(/(?<=[.!?])\s+(?=[A-Z])/);
  const schoon = zinnen.filter((z) => !WETSVERWIJZING_RX.test(z));
  return schoon.join(' ').trim();
}

const wetsverwijzingenVerwijderd = [];
for (const ap of normalised) {
  const origineel = String(ap.juridisch_kader || '');
  if (!origineel || !WETSVERWIJZING_RX.test(origineel)) continue;
  const schoon = zonderWetsverwijzing(origineel);
  ap.juridisch_kader = schoon;
  wetsverwijzingenVerwijderd.push({ id: ap.id, categorie: ap.categorie, verwijderd: origineel.slice(0, 200) });
  console.warn(`[Parse Flex Analysis JSON] wetsverwijzing uit "${ap.id}" (${ap.categorie}) verwijderd: ${origineel.slice(0, 120)}`);
}

const samenvatting = String(parsed.samenvatting || '').trim();

// Haal de drie specialist-bevindingen op (Parse * Analyse JSON zit elk in
// de directe voorouder-chain, dus $() is hier betrouwbaar).
let verervingItems = [];
let lastenItems = [];
let burgerlijkeItems = [];
let partijenItems = [];
try {
  const v = $('Parse Vererving JSON').first()?.json;
  if (Array.isArray(v?.vererving_aandachtspunten)) verervingItems = v.vererving_aandachtspunten;
} catch (e) { console.error('[Parse Flex Analysis JSON] vererving merge:', e?.message); }
try {
  const l = $('Parse Lasten JSON').first()?.json;
  if (Array.isArray(l?.lasten_aandachtspunten)) lastenItems = l.lasten_aandachtspunten;
} catch (e) { console.error('[Parse Flex Analysis JSON] lasten merge:', e?.message); }
try {
  const b = $('Parse Burgerlijke JSON').first()?.json;
  if (Array.isArray(b?.burgerlijke_aandachtspunten)) burgerlijkeItems = b.burgerlijke_aandachtspunten;
} catch (e) { console.error('[Parse Flex Analysis JSON] burgerlijke merge:', e?.message); }
try {
  const p = $('Parse Partijen JSON').first()?.json;
  if (Array.isArray(p?.partijen_aandachtspunten)) partijenItems = p.partijen_aandachtspunten;
} catch (e) { console.error('[Parse Flex Analysis JSON] partijen merge:', e?.message); }

// Deterministisch gelezen bedragen uit het opdracht-stuk. Die krijgen in de
// categorie 'Bedragen' voorrang op de LLM, net zoals de specialisten dat in hun
// eigen categorie hebben — de LLM las daar structureel de verkeerde getallen.
let bedragenItems = [];
let bedragenInStukken = [];
try {
  const bf = $('Build Flex Analysis Prompt').first()?.json;
  if (Array.isArray(bf?.bedragen_findings)) bedragenItems = bf.bedragen_findings;
  if (Array.isArray(bf?.bedragen_in_stukken)) bedragenInStukken = bf.bedragen_in_stukken;
} catch (e) { console.error('[Parse Flex Analysis JSON] bedragen merge:', e?.message); }

// Filter mega-prompt items in de vier specialist-categorieën. Specialist
// heeft voorrang; alleen als de specialist 0 items teruggaf mag mega-prompt
// die categorie nog vullen.
const RESERVED = {
  'vererving': verervingItems,
  'lasten en beperkingen': lastenItems,
  'burgerlijke staat': burgerlijkeItems,
  'object en partijen': partijenItems,
  'bedragen': bedragenItems,
};
// 'Bedragen' is volledig deterministisch: die categorie wordt in code gevuld en
// de LLM mag er niets aan toevoegen, ook niet als de code niets te melden heeft.
// Reden: over acht testruns leverde het model daar geen enkele juiste bevinding
// op, wél omgekeerde regels ("de hoofdsom moet groter zijn dan de
// inschrijving"), vergelijkingen die nergens op slaan (koopsom naast een
// hypotheekinschrijving) en herhalingen van wat andere specialisten al melden.
// Bij dit soort controlelijsten is een vals punt duurder dan een gemist punt.
// Mist de deterministische kant iets, dan is dat een nieuwe regel in
// controleerBedragen() — testbaar — en geen hoop dat het model het ziet.
const ALTIJD_DETERMINISTISCH = new Set(['bedragen']);
const llmBedragenGeweerd = [];
const filteredNorm = normalised.filter((ap) => {
  const cat = String(ap?.categorie || '').toLowerCase();
  if (ALTIJD_DETERMINISTISCH.has(cat)) {
    llmBedragenGeweerd.push({ id: ap.id, titel: ap.titel });
    console.warn(`[Parse Flex Analysis JSON] LLM-punt "${ap.id}" in ${ap.categorie} geweerd: die categorie is deterministisch`);
    return false;
  }
  const owner = RESERVED[cat];
  if (!owner) return true;
  return owner.length === 0;
});

// Alleen punten die van de LLM komen worden op verzonnen bedragen getoetst. Een
// deterministische bevinding rekent zelf ("150.000 plus 52.500 is 202.500"), en
// dat rekenresultaat hoeft niet letterlijk in de stukken te staan.
const llmAfkomstig = new Set(filteredNorm);

// Een punt zonder titel of zonder constatering is voor de behandelaar niets
// waard; het model levert er af en toe één op (waargenomen: leeg punt met
// alleen "[3]" als juridisch kader, een verdwaalde bronverwijzing). Die gaan
// eruit voordat er geteld en gesorteerd wordt.
function isBruikbaar(ap) {
  return Boolean(String(ap?.titel || '').trim()) && Boolean(String(ap?.constatering || '').trim());
}
const seenM = new Set();
const merged = [];
const leeg = [];
for (const ap of [...verervingItems, ...lastenItems, ...burgerlijkeItems, ...partijenItems, ...bedragenItems, ...filteredNorm]) {
  const id = String(ap?.id || '').trim();
  if (id && seenM.has(id)) continue;
  if (!isBruikbaar(ap)) {
    leeg.push(id || '(zonder id)');
    console.warn(`[Parse Flex Analysis JSON] leeg punt "${id}" geweerd: geen titel of constatering`);
    continue;
  }
  if (id) seenM.add(id);
  merged.push(ap);
}
// --- Bronbewaking ---------------------------------------------------------
// Een aandachtspunt mag alleen leunen op stukken die daadwerkelijk zijn
// aangeleverd. Het model deed dat niet uit zichzelf: op een upload met alleen
// twee BRP-uitdraaien kwam er een punt terug dat "de kadastrale
// eigendomsinformatie toont dat slechts één persoon als eigenaar is vermeld"
// — een verzonnen constatering uit een stuk dat niet bestond. De prompt
// waarschuwt er nu voor, maar een 7B-model is daarop geen garantie; dit filter
// wel. Een punt dat een niet-aangeleverd stuk aanhaalt, gaat eruit.
const ZAAKSOORTEN = (() => {
  try {
    const v = $('Aggregate Markdowns').first()?.json?.zaaksoorten;
    return Array.isArray(v) && v.length ? v : ['hypotheek'];
  } catch (_) { return ['hypotheek']; }
})();
const ZAAKSOORT = ZAAKSOORTEN.join('+');
const AANWEZIG = (() => {
  try { return $('Aggregate Markdowns').first()?.json?.bronnen_aanwezig || {}; }
  catch (_) { return {}; }
})();
const BRON_KLASSEN = {
  passeeropdracht: 'passeeropdracht', bank: 'passeeropdracht',
  notarisinstructie: 'passeeropdracht', nti: 'passeeropdracht',
  // Bij een levering neemt de koopovereenkomst de plaats van de passeeropdracht
  // in; het model noemt haar dan ook zo in 'bronnen'. Zonder deze aliassen valt
  // zo'n punt buiten de bronbewaking.
  koopovereenkomst: 'passeeropdracht', koopakte: 'passeeropdracht',
  leveringsopdracht: 'passeeropdracht', koopcontract: 'passeeropdracht',
  kadaster: 'kadaster', kadastraal: 'kadaster', eigendomsinformatie: 'kadaster',
  hypotheekinformatie: 'kadaster', hypothecair: 'kadaster',
  brp: 'brp', 'basisregistratie personen': 'brp', persoonslijst: 'brp',
};
// Ook de lopende tekst telt mee: het model noemt een stuk regelmatig in de
// constatering zonder het in 'bronnen' te zetten.
const TEKST_KLASSEN = [
  ['kadaster', /kadastrale?\s+(?:eigendoms|hypotheek)?informatie|kadastrale?\s+(?:uitdraai|bericht|gegevens)|\bkadaster\b|eigendomsinformatie/i],
  ['passeeropdracht', /\bpasseeropdracht\b|\bnotarisinstructie\b|\bkoopovereenkomst\b|\bkoopakte\b|\bleveringsopdracht\b/i],
  ['brp', /\bBRP\b|basisregistratie\s+personen|persoonslijst/i],
];
// 'Er is geen eigendomsinformatie aangeleverd' en 'de passeeropdracht bevat
// geen gegevens over de eigenaren' zijn juist cór-recte constateringen; alleen
// een bewéring uít het ontbrekende stuk is fout. De ontkenning kan vóór of ná
// de bronvermelding staan ("bevatten geen informatie"), dus wordt de hele zin
// beoordeeld en niet alleen wat eraan voorafgaat.
const ONTKENNING_RX = /\b(geen|niet|zonder|ontbreek\w*|ontbrekend\w*|afwezig|onbekend|nog\s+op\s+te\s+vragen)\b/i;
function noemtBronBewerend(tekst, rx) {
  return String(tekst || '')
    .split(/[.;!?]+\s+/)
    .some((zin) => rx.test(zin) && !ONTKENNING_RX.test(zin));
}
function ontbrekendeBronVan(ap) {
  const klassen = new Set();
  for (const b of ap.bronnen || []) {
    const k = BRON_KLASSEN[String(b).toLowerCase().trim()];
    if (k) klassen.add(k);
  }
  const tekst = `${ap.constatering || ''} ${ap.juridisch_kader || ''}`;
  for (const [klasse, rx] of TEKST_KLASSEN) {
    if (noemtBronBewerend(tekst, rx)) klassen.add(klasse);
  }
  for (const k of klassen) if (AANWEZIG[k] === false) return k;
  return '';
}
// De omgekeerde fout: een punt dat meldt dat een stuk ONTBREEKT terwijl het
// juist is aangeleverd. Bij een levering kwam dat er standaard uit — "Er is
// geen passeeropdracht aangeleverd" als los aandachtspunt, terwijl dat stuk bij
// een levering niet bestaat en de koopovereenkomst (dezelfde bronklasse) er wel
// was. De prompt verbiedt het al; dit is het vangnet. Alleen een punt dat het
// STUK ZELF ontbrekend noemt gaat eruit — "de modelakte-versie ontbreekt in de
// passeeropdracht" gaat over een veld in een aanwezig stuk en blijft staan.
const ONTBREEKT_RX = [
  ['passeeropdracht', /\b(?:geen|zonder)\s+(?:bank-?\s*)?(?:passeeropdracht|notarisinstructie|koopovereenkomst|koopakte|leveringsopdracht)\b|\b(?:passeeropdracht|notarisinstructie|koopovereenkomst|koopakte|leveringsopdracht)\s+(?:is\s+|zijn\s+)?(?:niet\s+(?:aangeleverd|aanwezig|bijgevoegd|overgelegd)|ontbreekt)/i],
  ['kadaster', /\b(?:geen|zonder)\s+(?:kadastrale?\s+)?(?:eigendomsinformatie|kadastrale?\s+informatie)\b|\beigendomsinformatie\s+(?:is\s+)?(?:niet\s+aangeleverd|ontbreekt)/i],
  ['brp', /\b(?:geen|zonder)\s+(?:BRP|persoonsinzage|persoonslijst)\b|\bBRP[- ]?(?:inzage|bevraging)?\s+(?:is\s+)?(?:niet\s+aangeleverd|ontbreekt)/i],
];
// Bij een levering blijft het model om hypotheekstukken vragen: "Er is geen
// bank of passeeropdracht aangeleverd, hoewel deze nodig zijn voor de levering"
// en "Er zijn geen hypotheekstukken aangeleverd". Dat is geen gebrek maar een
// verkeerde verwachting — die stukken hóren niet bij een eigendomsoverdracht.
// De prompt zegt het al; hier wordt het afgedwongen. De lijst noemt alleen
// STUKSOORTEN die in een levering niet bestaan. Bewust niet het losse woord
// 'bank': "er is geen aflosnota van de bank aangeleverd" is bij een levering
// juist een terecht punt (die nota is nodig voor het royement), en een
// bankgarantie hoort net zo goed bij een koop. Een bestaande hypotheek
// bespreken mag ook — alleen het VRAGEN om hypotheekpapieren gaat eruit.
const HYPOTHEEKSTUK_RX = /\bpasseeropdracht\b|\bnotarisinstructie\b|\bhypotheekstuk\w*|\bhypotheekakte\b|\bhypotheekbedrag\b|\bhypotheekopdracht\b|\bbankvolmacht\b|\bmodelakte\w*|\bNHG\b/i;
const MIST_RX = /\b(geen|zonder|ontbrekend\w*|ontbreek\w*|niet\s+(aangeleverd|aanwezig|bijgevoegd|overgelegd|beschikbaar))\b/i;
function vraagtOmHypotheekstukBijLevering(ap) {
  // Alleen bij een zuivere levering. Passeert er ook een hypotheek, dan is
  // vragen om de passeeropdracht of de bankvolmacht juist terecht.
  if (!ZAAKSOORTEN.includes('levering') || ZAAKSOORTEN.includes('hypotheek')) return false;
  const zinnen = `${ap.titel || ''}. ${ap.constatering || ''}`.split(/(?<=[.!?])\s+|\s+—\s+/);
  return zinnen.some((z) => HYPOTHEEKSTUK_RX.test(z) && MIST_RX.test(z));
}

// Een bedrag dat in geen enkel aangeleverd stuk voorkomt, is verzonnen. Geldt
// voor elk punt dat van de LLM komt — Bedragen is inmiddels deterministisch,
// maar ook een punt in Documentatie mag geen eigen getallen introduceren.
// Afgeronde bedragen zonder centen (bv. "€ 425.000") tellen ook als de stukken
// € 425.000,00 noemen.
function verzonnenBedrag(ap) {
  if (!bedragenInStukken.length) return null;
  const tekst = `${ap.titel || ''} ${ap.constatering || ''} ${ap.juridisch_kader || ''}`;
  const rx = /(?:€|EUR)\s*([\d.,]+)/gi;
  let m;
  while ((m = rx.exec(tekst))) {
    const ruw = String(m[1]).trim().replace(/\s/g, '').replace(/^[.,]+/, '').replace(/[.,]+$/, '');
    if (!ruw) continue;
    const nl = /^\d{1,3}(\.\d{3})*(,\d{1,2})?$/.test(ruw);
    const genormaliseerd = nl ? ruw.replace(/\./g, '').replace(',', '.') : ruw.replace(/,/g, '');
    const getal = Number.parseFloat(genormaliseerd);
    if (!Number.isFinite(getal)) continue;
    const cent = Math.round(getal * 100);
    if (!bedragenInStukken.includes(cent)) return `${m[0]}`;
  }
  return null;
}

function noemtAanwezigStukOntbrekend(ap) {
  const tekst = `${ap.titel || ''}. ${ap.constatering || ''}`;
  for (const [klasse, rx] of ONTBREEKT_RX) {
    if (AANWEZIG[klasse] === true && rx.test(tekst)) return klasse;
  }
  return '';
}

const geweerd = [];
const bewaakt = merged.filter((ap) => {
  const verzonnen = llmAfkomstig.has(ap) ? verzonnenBedrag(ap) : null;
  if (verzonnen) {
    geweerd.push({ id: ap.id, titel: ap.titel, bron: 'bedrag', reden: `noemt ${verzonnen}, dat in geen enkel stuk voorkomt` });
    console.warn(`[Parse Flex Analysis JSON] punt "${ap.id}" geweerd: bedrag ${verzonnen} komt in geen enkel stuk voor`);
    return false;
  }
  if (vraagtOmHypotheekstukBijLevering(ap)) {
    geweerd.push({ id: ap.id, titel: ap.titel, bron: 'zaaksoort', reden: 'vraagt om hypotheek-/bankstukken die niet bij een levering horen' });
    console.warn(`[Parse Flex Analysis JSON] punt "${ap.id}" geweerd: vraagt om hypotheek-/bankstukken bij een levering`);
    return false;
  }
  const tochAanwezig = noemtAanwezigStukOntbrekend(ap);
  if (tochAanwezig) {
    geweerd.push({ id: ap.id, titel: ap.titel, bron: tochAanwezig, reden: 'noemt een aangeleverd stuk ontbrekend' });
    console.warn(`[Parse Flex Analysis JSON] punt "${ap.id}" geweerd: noemt ${tochAanwezig} ontbrekend, maar die is aangeleverd`);
    return false;
  }
  const ontbrekend = ontbrekendeBronVan(ap);
  if (!ontbrekend) return true;
  geweerd.push({ id: ap.id, titel: ap.titel, bron: ontbrekend });
  console.warn(`[Parse Flex Analysis JSON] punt "${ap.id}" geweerd: leunt op ${ontbrekend}, niet aangeleverd`);
  return false;
});
merged.length = 0;
merged.push(...bewaakt);

const ORDER_M = { kritiek: 0, aandacht: 1, info: 2 };
merged.sort((a, b) => (ORDER_M[a.ernst] ?? 9) - (ORDER_M[b.ernst] ?? 9));

// Deterministische, gegarandeerd consistente samenvatting-aanvulling. De LLM
// beschrijft het dossier feitelijk (zonder oordeel over aandachtspunten); de
// telling hieronder komt uit de daadwerkelijk samengevoegde bevindingen, zodat
// de samenvatting die nooit meer tegenspreekt (fix observatie 2).
const kritiekCount = merged.filter((x) => x.ernst === 'kritiek').length;
const aandachtCount = merged.filter((x) => x.ernst === 'aandacht').length;
const infoCount = merged.filter((x) => x.ernst === 'info').length;

const delen = [];
if (kritiekCount) delen.push(`${kritiekCount}\u00d7 kritiek`);
if (aandachtCount) delen.push(`${aandachtCount}\u00d7 aandacht`);
if (infoCount) delen.push(`${infoCount}\u00d7 info`);

let bevindingenZin;
if (delen.length === 0) {
  bevindingenZin = 'De analyse signaleert geen bijzondere juridische aandachtspunten.';
} else {
  bevindingenZin = `De analyse signaleert ${merged.length} aandachtspunt${merged.length === 1 ? '' : 'en'} (${delen.join(', ')}).`;
  const kritiekTitels = merged.filter((x) => x.ernst === 'kritiek').map((x) => x.titel).filter(Boolean);
  if (kritiekTitels.length) bevindingenZin += ` Kritiek: ${kritiekTitels.join('; ')}.`;
}

// --- Wat is er níét getoetst? ---------------------------------------------
// De bronbewaking hierboven haalt uitspraken weg over stukken die ontbreken.
// Daarmee wordt een gat stil: zonder eigendomsinformatie is er niets over
// rechthebbenden of beslagen te melden, en een lezer kan die stilte lezen als
// 'niets aan de hand'. Daarom staat hier expliciet welke toets niet gedaan is.
// Wat er niet getoetst is, hangt af van de zaaksoort: bij een levering mist geen
// 'passeeropdracht' maar een koopovereenkomst, en gaat het niet om leninggegevens.
const NIET_GETOETST_OPDRACHT = {
  hypotheek: 'de leninggegevens en de voorwaarden van de bank — geen passeeropdracht aangeleverd',
  levering: 'de koopsom, de ontbindende voorwaarden en de leveringsafspraken — geen koopovereenkomst of leveringsopdracht aangeleverd',
  'hypotheek+levering': 'de koopsom en de leninggegevens — geen koopovereenkomst en geen passeeropdracht aangeleverd',
};
const NIET_GETOETST = {
  kadaster: 'rechthebbenden en beschikkingsbevoegdheid, beslagen, beperkte rechten en bestaande hypotheken — geen kadastrale eigendoms- of hypotheekinformatie aangeleverd',
  passeeropdracht: NIET_GETOETST_OPDRACHT[ZAAKSOORT] || NIET_GETOETST_OPDRACHT.hypotheek,
  brp: 'de actuele burgerlijke staat — geen BRP- of persoonsinzage aangeleverd',
};
const nietGetoetst = Object.keys(NIET_GETOETST)
  .filter((k) => AANWEZIG[k] === false)
  .map((k) => NIET_GETOETST[k]);
const nietGetoetstZin = nietGetoetst.length
  ? 'Niet getoetst: ' + nietGetoetst.map((t) => t.replace(' — ', ' (') + ')').join('; ') + '.'
  : '';

const finalSamenvatting = [samenvatting, bevindingenZin, nietGetoetstZin].filter(Boolean).join(' ').trim();

return [{
  json: {
    analysis: {
      samenvatting: finalSamenvatting,
      aandachtspunten: merged,
      niet_getoetst: nietGetoetst
    },
    bronbewaking: {
      aanwezig: AANWEZIG,
      geweerd,
      lege_punten: leeg,
      wetsverwijzingen_verwijderd: wetsverwijzingenVerwijderd,
      llm_bedragen_geweerd: llmBedragenGeweerd,
    },
    counts: {
      kritiek: kritiekCount,
      aandacht: aandachtCount,
      info: infoCount,
      totaal: merged.length,
      specialisten: {
        bedragen_deterministisch: bedragenItems.length,
        vererving: verervingItems.length,
        lasten: lastenItems.length,
        burgerlijke: burgerlijkeItems.length,
        partijen: partijenItems.length
      }
    }
  }
}];

const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Create Job').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

werkJobBij({ status: 'document', fase: 3 });

// Args naar tijdelijk JSON-bestand schrijven voor genereer_juridische_analyse.py
// (analyse-only flow). Python-script verwijdert het bestand na inlezen.
const execId = String($execution.id || 'single').replace(/[^0-9A-Za-z_-]/g, '_').slice(0, 32);
const argsFile = `/tmp/n8n_args_flex_analyse_${execId}_${Date.now()}.json`;
const meta = $('Aggregate Markdowns').first()?.json || {};
const j = $json || {};
const payload = {
