const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Create Job').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

// Schrijft het eindresultaat in het jobbestand; de webapp haalt het bij de
// volgende poll op. De HTTP-respons (het job_id) is al bij binnenkomst
// verstuurd, dus hier gaat niets meer over de lijn.
//
// De payload-vorm is ongewijzigd gebleven ten opzichte van de synchrone versie,
// zodat de webapp dezelfde velden blijft lezen.
const analysisCmdNode = $('Generate Flex Analysis DOCX').first()?.json || {};
const analysisCmdStdout = String(analysisCmdNode.stdout || '');
const analysisCmdErr = String(analysisCmdNode.stderr || '');
const analysisMatch = analysisCmdStdout.match(/SUCCESS:\s*(.+)/);
const analysisPath = analysisMatch ? analysisMatch[1].trim() : '';
const analysisFilename = analysisPath ? analysisPath.split('/').pop() : '';

const analysisDataNode = $('Parse Flex Analysis JSON').first()?.json || {};
const analysis = analysisDataNode.analysis || { samenvatting: '', aandachtspunten: [] };
const counts = analysisDataNode.counts || {
  kritiek: 0,
  aandacht: 0,
  info: 0,
  totaal: (analysis.aandachtspunten || []).length,
};

const meta = $('Aggregate Markdowns').first()?.json || {};

const generationWarning = analysisPath
  ? null
  : `Analyse-DOCX niet gegenereerd. stdout=${analysisCmdStdout.slice(0, 200)}; stderr=${analysisCmdErr.slice(0, 200)}`;

const resultaat = {
  // In de synchrone versie stond hier altijd `true`; nu de job een status
  // krijgt moet dit wel de werkelijkheid volgen, anders meldt de webapp een
  // geslaagde analyse zonder document.
  success: !!analysisPath,
  mode: 'analyse',
  zaaksoort: meta.zaaksoort || 'hypotheek',
  filename: null,
  file_path: null,
  download_url: null,
  bank_id: meta.bankId || null,
  bank_display_name: meta.bankDisplayName || null,
  klant_samenvatting: meta.klantSamenvatting || '',
  zaaknummer: meta.zaaknummer || '',
  document_count: meta.documentCount || 0,
  analysis: {
    ...analysis,
    counts,
    filename: analysisFilename || null,
    file_path: analysisPath || null,
    download_url: analysisFilename
      ? `http://localhost:8080/output/${analysisFilename}`
      : null,
    generation_warning: generationWarning,
  },
};

const job = werkJobBij({
  status: resultaat.success ? 'klaar' : 'fout',
  fase: 4,
  fout: generationWarning,
  resultaat,
});

return [{ json: job }];

// Maakt het jobbestand aan waar de rest van de workflow zijn voortgang in
// bijhoudt, en laat de binaries ongemoeid doorlopen naar Split Input Files.
const item = $input.first();

const fs = require('fs');
const JOB_DIR = '/data/shared/jobs';
const nu = new Date();
const stempel =
  nu.getFullYear() +
  String(nu.getMonth() + 1).padStart(2, '0') +
  String(nu.getDate()).padStart(2, '0') +
  '_' +
  String(nu.getHours()).padStart(2, '0') +
  String(nu.getMinutes()).padStart(2, '0') +
  String(nu.getSeconds()).padStart(2, '0');
const jobId = `analyse_${stempel}_${String($execution.id || Math.random().toString(36).slice(2))}`
  .replace(/[^0-9A-Za-z_-]/g, '_');

fs.mkdirSync(JOB_DIR, { recursive: true });

// Oude jobbestanden opruimen; ze bevatten dossierinhoud en horen niet langer te
// blijven staan dan nodig is om het resultaat op te halen.
const BEWAARTERMIJN_MS = 24 * 60 * 60 * 1000;
try {
  for (const naam of fs.readdirSync(JOB_DIR)) {
    if (!naam.endsWith('.json')) continue;
    const pad = `${JOB_DIR}/${naam}`;
    if (Date.now() - fs.statSync(pad).mtimeMs > BEWAARTERMIJN_MS) fs.unlinkSync(pad);
  }
} catch (_) {
  // Best-effort: een nieuwe analyse mag hier niet op stuklopen.
}

const documentCount = Object.keys(item.binary || {}).length;

fs.writeFileSync(
  `${JOB_DIR}/${jobId}.json`,
  JSON.stringify({
    job_id: jobId,
    soort: 'analyse',
    status: 'documenten lezen',
    fase: 1,
    document_count: documentCount,
    resultaat: null,
    fout: null,
    gestart_op: nu.toISOString(),
    bijgewerkt_op: nu.toISOString(),
  }),
  'utf8'
);

return [{ json: { ...(item.json || {}), jobId, documentCount }, binary: item.binary }];
